    "Hose Nozzle/Spray Gun": "ரெயின் கன் || ஹோஸ் கனெக்டர்கள் & இணைப்புகள் || சொட்டு பக்கவாட்டு குழாய் (12 மிமீ) || ஆன்லைன் சொட்டு உமிழ்ப்பான்கள் || சொட்டு நாடா || குரோமெட்ஸ்/டேக்-ஆஃப் கனெக்டர்கள்",
    "Impact/Rotary Sprinkler": "வென்டூரி உர ஊசி",
    "Micro Sprinklers": "திரை வடிகட்டி || வட்டு வடிகட்டி || அழுத்த அளவுகோல் || காற்று வெளியீட்டு வால்வு || எண்ட் கேப்ஸ் (பேக்) || டீ/எல்போ/ஜைனர் பொருத்துதல்கள் (பேக்) || சொட்டு ஸ்டாக்ஸ் (பேக்) || உரமிடும் தொட்டி || மூங்கில் பங்குகள் (பேக்) || தக்காளி கூண்டுகள் || டிரெல்லிஸ் நெட்டிங் || தாவர ஆதரவு கிளிப்புகள் || தேங்காய் கயிறு || வயர் மெஷ் ஆதரவு || போன்சாய் பயிற்சி கம்பி (அலுமினியம்/செம்பு)",
    "Overhead Sprinkler System": "ஏறும் தாவர ஆதரவு சட்டகம் || வெல்க்ரோ ஆலை டைஸ்",
    "Irrigation Water Timer": "சணல் கயிறு || தாவர ஆதரவு வளையங்கள் || எஸ்பாலியர் வயர் கிட் || பரப்புதல் வெப்ப பாய் || பரப்புதல் தட்டுகளை வெட்டுதல் || வளரும் நாடா || உரம் வெப்பமானி || உரம் டர்னர் கருவி || மக்கும் உரம் பைகள் || தாவர லேபிள்கள்/குறிப்பான்கள் (பேக்) || கார்டன் ட்வைன் || நாற்றங்கால் தாவர குறிச்சொற்கள் (பேக்) || அளவிடும் ஸ்கூப்",
