    "Measuring Scoop": "Measuring Scoop",
    "Garden Apron": "கார்டன் ஏப்ரன் || முழங்கால் திண்டு || கார்டன் டிராலி/கேடி || மண் சல்லடை || மண்ணின் ஈரப்பதம் மீட்டர் || மண் pH பரிசோதனை கருவி || மண் வெப்பமானி || நிகர பானைகள் || LECA (களிமண் கூழாங்கற்கள்) || ராக்வூல் க்யூப்ஸ் || ஹைட்ரோபோனிக் ஊட்டச்சத்து தீர்வு (A & B)",
    "Kneeling Pad": "pH உயர்/கீழ் தீர்வு",
    "Garden Trolley/Caddy": "EC/TDS மீட்டர் || ஏர் பம்ப் & ஏர் ஸ்டோன் || ஆழமான நீர் கலாச்சாரம் (DWC) பக்கெட் கிட் || NFT சேனல்கள் || ஹைட்ரோபோனிக் ரிசர்வாயர் டேங்க் || ஹைட்ரோபோனிக் டவர் கிட் || கடற்பாசிகள்/ஓயாசிஸ் க்யூப்ஸ் வளருங்கள் || உணர்ந்த செங்குத்து தோட்ட பாக்கெட்டுகள் || மாடுலர் கிரீன் வால் பேனல் || செங்குத்து ஆலை கோபுரம் || சுவரில் பொருத்தப்பட்ட பிளாண்டர் அடைப்புக்குறிகள் || வாழும் சுவர் நீர்ப்பாசன கிட் || செங்குத்துத் தோட்டம் ட்ரெல்லிஸ் சட்டகம் || அடுக்கி வைக்கக்கூடிய நடவு அமைப்பு",
    "Soil Sieve": "கையால் புல் அறுக்கும் இயந்திரம் || புல் டிரிம்மர்/பிரஷ் கட்டர் || புல்வெளி மேல்-உடுத்தி மணல் || தரை உர கூர்முனை || கார்டன் பார்டர் ஸ்டோன்ஸ் || புல்வெளி விளிம்பு பட்டைகள் || கூரான புல்வெளி காற்றோட்டம் || இயற்கை டர்ஃப் ரோல்ஸ் || நிலப்பரப்பு/களை-தடை துணி",
    "Soil Moisture Meter": "நதி கூழாங்கற்கள் || கருப்பு பளபளப்பான கூழாங்கற்கள் || வெள்ளை மார்பிள் சிப்ஸ் || வண்ண அலங்கார சரளை || கோகோ மல்ச் சிப்ஸ் || மரப்பட்டை தழைக்கூளம் || அலங்கார எரிமலை பாறைகள் || நொறுக்கப்பட்ட கல் சரளை கலவை || பச்சை நிழல் வலை (50%) || கருப்பு நிழல் வலை || ஆலங்கட்டி எதிர்ப்பு வலை",
    "Soil pH Test Kit": "பறவை பாதுகாப்பு வலை || பூச்சி-தடுப்பு அக்ரோ நெட்",
    "Soil Thermometer": "உறைபனி பாதுகாப்பு ஃபிலீஸ் கவர் || பிளாஸ்டிக் மல்ச்சிங் படம்",
