    "Green Shade Net (35%)": "பச்சை நிழல் வலை (35%) || பச்சை நிழல் வலை (75%) || பூச்சி-விலக்கு வலை",
    "Green Shade Net (75%)": "பயிர் வரிசை கவர் துணி || கிரீன்ஹவுஸ் UV பாலி ஃபிலிம் || கிரீன்ஹவுஸ் ஃப்ரேம் கிளிப்புகள் (பேக்) || வெளியேற்ற மின்விசிறி || ஆவியாக்கும் கூலிங் பேட் || கிரீன்ஹவுஸ் தெர்மோமீட்டர்/ஹைக்ரோமீட்டர்",
    "Pest-Exclusion Netting": "காற்றோட்ட வலை",
    "Crop Row Cover Fabric": "நிழல் துணி கிளிப்புகள் (பேக்) || பாலி ஃபிலிம் ரிப்பேர் டேப் || கிரீன்ஹவுஸ் கட்டமைப்பு பொருத்துதல்கள் (பேக்) || ஸ்மார்ட் கிரீன்ஹவுஸ் காலநிலை கட்டுப்பாட்டாளர் || ஷேட் ஹவுஸ் நெட்டிங் ரோல் || ஒட்டும் பூச்சி பொறிகள் (பேக்) || பெரோமோன் லூரெஸ் (பேக்) || பறவை கூர்முனை || மீயொலி பூச்சி விரட்டி || எலி பொறிகள் || கொசு லார்விசைட் டங்க்ஸ் || பழ ஈ பொறிகள் || எறும்பு தூண்டில் நிலையங்கள் (பேக்) || தாவர பேக்கேஜிங் பெட்டிகள் (பேக்) || நர்சரி பாலி ஸ்லீவ்ஸ் (பேக்) || குமிழி மடக்கு (தாவர கப்பல் போக்குவரத்து) || நெளி தாவர போக்குவரத்து பெட்டிகள் (பேக்) || சணல் பேக்கேஜிங் பைகள் (பேக்) || காகித விதை பொட்டலங்கள் (பேக்) || செடிகளுக்கான கிஃப்ட்-ரேப் ஸ்லீவ்ஸ் (பேக்) || பிராண்டட் நர்சரி கேரி பேக்ஸ் (பேக்) || கட்டு கயிறு",
    "Greenhouse UV Poly Film": "வெற்று தாவர லேபிள்கள் (பேக்) || நீர்ப்புகா மார்க்கர் பேனாக்கள் (பேக்) || ஒட்டுதல் ரப்பர் பட்டைகள் (பேக்) || நர்சரி பதிவு குறிச்சொற்கள் (பேக்) || ஜிப் டைஸ் (பேக்) || ஸ்டாக்கிங்கிற்கான கேபிள் டைஸ் (பேக்) || நர்சரி தட்டு சுத்தம் செய்யும் தூரிகை || டிஸ்போசபிள் நைட்ரைல் கையுறைகள் (பேக்) || மறைத்தல்/லேபிளிங் டேப் || நர்சரி டிரான்ஸ்போர்ட் கிரேட்ஸ் || தாவரம் சுமந்து செல்லும் தள்ளுவண்டி || நர்சரி ஸ்டேஜிங் பெஞ்ச்/டேபிள் || விலைக் குறி வைத்திருப்பவர்கள்/குறியீடு (பேக்) || பூச்சி உருப்பெருக்கி கண்ணாடி || கார்டன் டைரி/திட்டமிடுபவர் || பல்நோக்கு தாவர உறவுகள் (பேக்) || ஒட்டுதல் கிளிப்புகள் (பேக்) || வளரும் கத்தி",
