    "Foxtail Agave": "பெருவியன் ஆப்பிள் கற்றாழை || கோல்டன் பீப்பாய் கற்றாழை || பன்னி இயர் கற்றாழை (ஓபுண்டியா) || சந்திரன் கற்றாழை || பிஷப்\\ || ஓல்ட் மேன் கற்றாழை || கிறிஸ்துமஸ் கற்றாழை || எலி வால் கற்றாழை || லேடி ஃபிங்கர் கற்றாழை (மம்மிலேரியா) || முட்கள் நிறைந்த பேரிக்காய் || எச்செவேரியா டேபிள் டாப் || குழந்தை ரப்பர் ஆலை (மேசை மேல்) || நரம்பு தாவரம் (மேசை மேல்) || Gloxinia || சைனீஸ் மணி பிளாண்ட் (டேபிள் டாப்) || மினி எச்செவேரியா || திம்பிள் கற்றாழை || குழந்தை\\",
    "Pencil Cactus": "டேபிள் ஃபெர்ன் (மினி) || சீன பனியன் பொன்சாய் (ஃபிகஸ்) || ஜேட் போன்சாய் || பிரேம்னா போன்சாய்",
    "African Milk Tree": "சீன ஜூனிபர் போன்சாய் || டென்ட்ரோபியம் ஆர்க்கிட்",
    "Living Stones (Lithops)": "நீல வந்தா || அந்துப்பூச்சி ஆர்க்கிட் (ஃபாலெனோப்சிஸ்)",
    "String of Bananas": "Corsage Orchid (Cattleya)",
    "Ox Tongue Plant (Gasteria)": "டான்சிங் லேடி ஆர்க்கிட் (ஆன்சிடியம்) || சிம்பிடியம் ஆர்க்கிட் || பிலிப்பைன்ஸ் கிரவுண்ட் ஆர்க்கிட் || மொகரா ஆர்க்கிட் || ஸ்கார்லெட் நட்சத்திரம் (குஸ்மேனியா) || தழல் வாள் (Vriesea) || வெள்ளி குவளை செடி (Aechmea)",
    "Desert Rose": "Blushing Bromeliad (Neoregelia)",
    "Moonstones (Pachyphytum)": "ஸ்பானிஷ் பாசி (காற்று ஆலை) || பாஸ்டன் ஃபெர்ன் || பறவை\\",
    "Peruvian Apple Cactus": "மெய்டன்ஹேர் ஃபெர்ன்",
