    "Silver Lace Fern (Table Fern)": "சில்வர் லேஸ் ஃபெர்ன் (டேபிள் ஃபெர்ன்) || வெப்பமண்டல பிட்சர் ஆலை (நேபெந்தஸ்) || வீனஸ் ஃப்ளைட்ராப் || கேப் சண்டே || ஊதா பிட்சர் ஆலை (சர்ராசீனியா) || நீர் பதுமராகம் || தண்ணீர் கீரை || கட்டைல் ​​(புல்ரஷ்) || பாப்பிரஸ் || நீர் லில்லி || தாமரை || ஈல் புல் (வல்லிஸ்னேரியா)",
    "Tropical Pitcher Plant (Nepenthes)": "யானை காது (குளம்) || ஹார்ட்லீஃப் பிலோடென்ட்ரான் (செங்குத்து)",
    "Venus Flytrap": "அம்புக்குறி (செங்குத்து) || பாஸ்டன் ஃபெர்ன் (செங்குத்து) || மோஸ் ரோஸ் (செங்குத்து) || சிலந்தி செடி (பச்சை சுவர்) || அலைந்து திரிந்த யூதர் (Tradescantia)",
    "Cape Sundew": "குழந்தை ரப்பர் ஆலை (பச்சை சுவர்) || இக்சோரா (மொட்டை மாடி) || குள்ள கொய்யா || மடகாஸ்கர் டிராகன் மரம் (Dracaena Marginata)",
    "Purple Pitcher Plant (Sarracenia)": "மினியேச்சர் ரோஸ் || எமரால்டு சிற்றலை பெப்பரோமியா || எச்செவேரியா (பால்கனி) || ட்ரைலிங் வெர்பெனா || ஸ்வீடிஷ் ஐவி (Plectranthus)",
    "Water Hyacinth": "புல்லுருவி கற்றாழை (ரிப்சாலிஸ்) || எலுமிச்சை || சுண்ணாம்பு || மா",
    "Water Lettuce": "கொய்யா",
    "Cattail (Bulrush)": "மாதுளை || கஸ்டர்ட் ஆப்பிள் || பப்பாளி || மல்பெரி || ஜமைக்கன் செர்ரி / ஸ்ட்ராபெரி மரம் || இந்திய ஜுஜுபி || குள்ள தேங்காய் || நட்சத்திரப் பழம் || பேஷன் ஃப்ரூட் || மெழுகு ஆப்பிள் || ஸ்ட்ராபெர்ரி || அத்தி || டிராகன் பழம் || திராட்சை || சப்போட்டா / சிக்கோ",
    "Papyrus": "பலாப்பழம் || துளசி",
