    "Mint": "புதினா || கொத்தமல்லி || ஆர்கனோ",
    "Coriander": "ரோஸ்மேரி || தைம் || புனித துளசி (துளசி) || பிட்டர்ஸ் ராஜா (நிலவேம்பு) || கோது கோலா (வல்லாரை)",
    "Oregano": "அலோ வேரா (மருந்து)",
    "Rosemary": "இந்திய நெல்லிக்காய் (ஆம்லா) || அஸ்வகந்தா || வேம்பு || மலபார் கொட்டை (ஆடாதோடை) || எலுமிச்சம்பழம் || ரோஜா வாசனை ஜெரனியம் || லாவெண்டர் || வெட்டிவேர் || கருப்பு மிளகு || இஞ்சி",
    "Thyme": "மஞ்சள் || கறிவேப்பிலை || இலவங்கப்பட்டை || கிராம்பு || துளசி || பேல் / பில்வா || பீபால் (புனிதமானது) || தாமரை (புனிதமானது) || அரேபிய மல்லிகை || சம்பக் || இக்சோரா (பட்டாம்பூச்சி) || லந்தானா (பட்டாம்பூச்சி) || இந்தியன் பர்த்வார்ட் (அரிஸ்டோலோச்சியா)",
    "Holy Basil (Tulsi)": "வெப்பமண்டல பால்வீடு || கோட் பட்டன்கள் (ட்ரைடாக்ஸ்) || காஸ்மோஸ் || சூரியகாந்தி || இந்திய பவள மரம் || சில்வர் ஓக் || பாட்டில் பிரஷ் || அரேபிய மல்லிகை (மணம்) || டியூபரோஸ் || இரவு பூக்கும் மல்லிகை || ஃபிராங்கிபானி (சிவப்பு) || நாஸ்டர்டியம் || ரோசெல்லே || பான்சி",
    "King of Bitters (Nilavembu)": "Casuarina / Beach She-Oak",
    "Gotu Kola (Vallarai)": "ஸ்க்ரூபைன் || கிரீடம் மலர் || கடற்கரை காலை மகிமை",
