    "Beach Morning Glory": "Beach Morning Glory",
    "Beach Cabbage (Scaevola)": "கடற்கரை முட்டைக்கோஸ் (ஸ்கேவோலா) || போர்டியா மரம் || காட்டு மல்லிகை (கடற்கரை) || மடகாஸ்கர் பாதாம் || அர்ஜுனா",
    "Portia Tree": "பஹேடா",
    "Wild Jasmine (Coastal)": "ஹரிடகி || கரஞ்ச் / பொங்கமியா",
    "Madagascar Almond": "மஹோகனி || ஆப்பிரிக்க மஹோகனி || வெள்ளை சிடார் || இந்திய மஹோகனி (டூன்) || கற்பூர மரம் || ஜாமுன்",
    "Arjuna": "புளி",
    "Baheda": "மஹுவா",
    "Haritaki": "பாகுல் || ருத்ராட்சம் || பலாஷ் / காட்டின் சுடர்",
    "Karanj / Pongamia": "பட்டு பருத்தி மரம் || கடல் செம்பருத்தி || அலெக்ஸாண்ட்ரியன் லாரல்",
    "Mahogany": "உண்மை அசோகா || ஜகரண்டா",
    "African Mahogany": "கடம்பா || புத்ரஞ்சிவா || பிங்க் ஷவர் மரம் || ஆர்க்கிட் மரம் (ஊதா) || ஆர்க்கிட் மரம் (வெள்ளை) || மஞ்சள் தபேபுயா || வெள்ளி எக்காளம் மரம் || வெள்ளை எக்காளம் மரம் || பீரங்கி மரம் || தொத்திறைச்சி மரம் || அழும் அத்தி மரம் || இந்திய லாரல் அத்தி || ஃபிகஸ் பாண்டா || மாக்னோலியா || ஆஸ்திரேலிய பைன் || நார்போக் தீவு பைன் || குக் பைன் || பாபாப் || குரங்கு புதிர் மரம் || டிராகன் இரத்த மரம் || அக்லோனெமா சிவப்பு || அக்லோனெமா வெள்ளி விரிகுடா || Philodendron Xanadu",
    "White Cedar": "Philodendron Selloum",
    "Indian Mahogany (Toon)": "மான்ஸ்டெரா டெலிசியோசா || டிஃபென்பாச்சியா காமில்",
