    "Dracaena Compacta": "டிராகேனா காம்பாக்டா || இந்தியாவின் டிராகேனா பாடல் || ஜமைக்காவின் டிராகேனா பாடல் || கார்டிலைன் சிவப்பு || கார்டிலைன் கிரீன் (டி பிளாண்ட்) || Acalypha Green || மிங் அராலியா || பலவகை அரலியா || பச்சை அராலியா || பலவகையான ஷெஃப்லெரா",
    "Dracaena Song of India": "பச்சை ஷெஃப்லெரா || துரண்டா கோல்டன் எட்ஜ் || பலவகையான துரந்தா",
    "Dracaena Song of Jamaica": "காமினி (ஆரஞ்சு மல்லிகை) || கார்டேனியா || மஞ்சள் மணிகள் (டெகோமா) || ஆரஞ்சு டெகோமா || மஞ்சள் அலமண்டா || ஊதா அல்லமண்டா || பிங்க் முஸ்ஸெண்டா",
    "Cordyline Red": "வெள்ளை முஸ்ஸெண்டா || ஃபயர்புஷ் (ஹமேலியா பேடென்ஸ்)",
    "Cordyline Green (Ti Plant)": "பட்டாசு ஆலை (ரஷ்யா) || ப்ளூ பிளம்பகோ || வெள்ளை பிளம்பகோ || காட்டு மல்லிகை (Clerodendrum Inerme)",
    "Acalypha Green": "சுடர்விடும் மகிமைபோவர் || மெக்சிகன் பெட்டூனியா (உயரமான) || குள்ள கிராஸாண்ட்ரா || பிலிப்பைன் வயலட் (பார்லேரியா) || சிவப்பு பெண்டாஸ் || பிங்க் பெண்டாஸ் || வெள்ளை பெண்டாஸ் || மஞ்சள் இக்சோரா || குள்ள இக்சோரா",
    "Ming Aralia": "சிவப்பு செம்பருத்தி || மஞ்சள் செம்பருத்தி || பலவகை செம்பருத்தி || சொர்க்கத்தின் பறவை || Loropetalum (சீன விளிம்பு மலர்) || இந்திய ஹாவ்தோர்ன் || படகு லில்லி (ரியோ டிரிகோலர்) || அலைந்து திரியும் யூதர் (ஜெப்ரினா)",
    "Variegated Aralia": "சிவப்பு மாற்றுத்திறனா",
    "Green Aralia": "மஞ்சள் மாற்றுத்திரா || பச்சை மாற்றுத்திறனா",
    "Variegated Schefflera": "இரத்த இலை (ஐரெசின்) || அஸ்பாரகஸ் ஃபெர்ன்",
    "Green Schefflera": "ஃபாக்ஸ்டெயில் ஃபெர்ன்",
