    "Foxtail Fern": "Foxtail Fern",
    "Liriope (Lily Turf)": "லிரியோப் (லில்லி டர்ஃப்) || டயனெல்லா (ஃப்ளாக்ஸ் லில்லி) || அகபந்தஸ் (ஆப்பிரிக்க லில்லி)",
    "Dianella (Flax Lily)": "Dietes Bicolor (Wild Iris)",
    "Agapanthus (African Lily)": "டயட்ஸ் கிராண்டிஃப்ளோரா || சமுதாயம் பூண்டு || குடை பனை (குள்ள சைபரஸ்) || பலவகை திருக்குறள் (பாண்டனஸ்) || ஸ்பைடர் லில்லி || கிரினம் லில்லி || கன்னா லில்லி || டே லில்லி || மழை லில்லி || வெள்ளை இஞ்சி லில்லி || சிவப்பு இஞ்சி (தீக்கோழி பிளம்) || ஹெலிகோனியா / லோப்ஸ்டர் கிளா || ஜூனிபர் || துஜா / மோர்பங்கி",
    "Dietes Bicolor (Wild Iris)": "Podocarpus || நீல நட்சத்திர ஜூனிபர் || நந்தினா (பரலோக மூங்கில்)",
    "Dietes Grandiflora": "யூஜீனியா ஹெட்ஜ் || பாக்ஸ்வுட் || Philodendron Birkin",
    "Society Garlic": "காலடியம் || பிளாக் மேஜிக் யானை காது || அலோகாசியா பாலி || பிங்க் சின்கோனியம் || பீஸ் லில்லி டோமினோ (வேறுவகை) || சிவப்பு அந்தூரியம் || வெள்ளை அந்தூரியம் || கிம்பர்லி ராணி ஃபெர்ன் || Blue Daze (Evolvulus)",
    "Umbrella Palm (Dwarf Cyperus)": "கசானியா || டயந்தஸ் / பிங்க்ஸ் || சால்வியா",
    "Variegated Screwpine (Pandanus)": "வெர்பெனா",
    "Spider Lily": "உண்ணி (கோரியோப்சிஸ்) || ப்ளூம் செலோசியா",
    "Crinum Lily": "குள்ள கோலியஸ் || Impatiens / Balsam",
    "Canna Lily": "பெகோனியா || மெழுகு பிகோனியா || ரெக்ஸ் பிகோனியா || டஸ்டி மில்லர் || லாவெண்டர் பருத்தி || வார்ம்வுட் (ஆர்டெமிசியா) || Stonecrop (Sedum) || பலவகையான யானை புஷ் || நீல சுண்ணாம்பு குச்சிகள் (செனிசியோ)",
