    "Tomato Seeds": "தக்காளி விதைகள் || பிரிஞ்சி (கத்தரிக்காய்) விதைகள் || ஓக்ரா (பிந்தி) விதைகள் || மிளகாய் விதைகள் || முட்டைக்கோஸ் விதைகள் || காலிஃபிளவர் விதைகள் || வெள்ளரி விதைகள் || சுரைக்காய் விதைகள் || பாகற்காய் விதைகள் || பூசணி விதைகள் || கேரட் விதைகள் || முள்ளங்கி விதைகள் || கீரை (பாலக்) விதைகள் || வெந்தய (மேத்தி) விதைகள் || வெங்காய விதைகள் || பிரஞ்சு பீன் விதைகள் || பச்சை பட்டாணி விதைகள் || கேப்சிகம் விதைகள் || முள்ளங்கி விதைகள் || பூசணி விதைகள் || ஜின்னியா விதைகள் || காஸ்மோஸ் விதைகள் || Petunia விதைகள் || சூரியகாந்தி விதைகள் || பால்சம் விதைகள் || Portulaca விதைகள் || வின்கா விதைகள் || Dianthus விதைகள் || ஆஸ்டர் விதைகள் || கயிலார்டியா விதைகள் || செலோசியா விதைகள் || துளசி (துளசி) விதைகள் || கொத்தமல்லி விதைகள் || புதினா விதைகள் || அஜ்வைன் விதைகள் || வெந்தய விதைகள் || எலுமிச்சம்பழ விதைகள் || பப்பாளி விதைகள் || தர்பூசணி விதைகள் || முலாம்பழம் விதைகள் || கொய்யா விதைகள் || எலுமிச்சை விதைகள் || முள்ளங்கி மைக்ரோகிரீன் விதைகள் || சூரியகாந்தி மைக்ரோகிரீன் விதைகள் || வெந்தய மைக்ரோகிரீன் விதைகள் || கடுகு மைக்ரோகிரீன் விதைகள் || ப்ரோக்கோலி மைக்ரோகிரீன் விதைகள் || பெர்முடா புல் விதை || டூப் புல் விதை || ரைகிராஸ் விதை",
