    "Maize Fodder Seed": "மக்காச்சோள தீவன விதை || உளுந்து தீவன விதை || லூசர்ன் (அல்பால்ஃபா) விதை",
    "Sorghum Fodder Seed": "கோதுமை தீவன விதை || அஸ்வகந்தா விதை || இசப்கோல் (சைலியம்) விதை",
    "Lucerne (Alfalfa) Seed": "துளசி விதை (மருத்துவ தரம்) || காலே விதைகள் || ப்ரோக்கோலி விதைகள் || கீரை விதைகள் || சுரைக்காய் விதைகள் || பெல் மிளகு விதைகள் || குல்மோஹர் விதைகள் || வேப்ப விதைகள் || செம்பருத்தி விதைகள் || Bougainvillea விதைகள் || அமல்டாஸ் விதைகள் || எளிய சுற்று டெரகோட்டா பானை (4-24 அங்குலம்) || ரிம்ட் டெரகோட்டா பாட் (4-24 அங்குலம்) || முட்கள் / பள்ளம் கொண்ட டெரகோட்டா பானை (4-24 அங்குலம்)",
    "Cowpea Fodder Seed": "பளபளப்பான-ரிம் டெரகோட்டா பாட் (4-24 அங்குலம்)",
    "Ashwagandha Seed": "வர்ணம் பூசப்பட்ட டெரகோட்டா பானை, வகைப்படுத்தப்பட்ட வண்ணங்கள் (4-24 அங்குலம்)",
    "Isabgol (Psyllium) Seed": "செட்டிநாடு பாணி டெரகோட்டா பானை (4-24 அங்குலம்) || டெரகோட்டா லாங் டாம் பாட் (6-24 அங்குலம்) || டெரகோட்டா போன்சாய் பானை, ஆழமற்ற (4-14 அங்குலம்) || அறுகோண டெரகோட்டா பிளான்டர் (8-14 அங்குலம்) || உருளை டெரகோட்டா பிளான்டர் (8-16 அங்குலம்) || டெரகோட்டா செவ்வகத் தொட்டி (12-24 அங்குலம்) || கூம்பு வடிவ டெரகோட்டா பிளான்டர் (8-12 அங்குலம்) || மெருகூட்டப்பட்ட பீங்கான் பானை, பல பூச்சுகள் (6-12 அங்குலம்)",
    "Tulsi Seed (Medicinal Grade)": "இரண்டு-தொனியில் படிந்த செராமிக் பாட் (6-12 அங்குலம்) || ஓவல் மெருகூட்டப்பட்ட செராமிக் பிளாண்டர் (8-12 அங்குலம்) || அறுகோண படிந்த செராமிக் பாட் (6-10 அங்குலம்) || செராமிக் சிலிண்டர் பிளான்டர், மெருகூட்டப்பட்ட (8-14 அங்குலம்)",
    "Kale Seeds": "செராமிக் பவுல் பிளாண்டர், மெருகூட்டப்பட்ட (8-12 அங்குலம்) || வட்டமான பிளாஸ்டிக் பானை, பல வண்ணங்கள் (4-18 அங்குலம்) || சதுர பிளாஸ்டிக் தோட்டம், பல வண்ணங்கள் (6-12 அங்குலம்)",
    "Broccoli Seeds": "ஓவல் பிளாஸ்டிக் பிளாண்டர் (8-14 அங்குலம்) || செவ்வக பிளாஸ்டிக் தொட்டி ஆலை (12-24 அங்குலம்) || குறுகலான பிளாஸ்டிக் பானை (8-14 அங்குலம்) || நார்-வலுவூட்டப்பட்ட பிளான்டர், பல முடித்தல் (10-24 அங்குலம்)",
    "Lettuce Seeds": "கூம்பு FRP ஆலை (12-24 அங்குலம்) || உருளை FRP ஆலை (12-30 அங்குலம்) || கியூப் எஃப்ஆர்பி பிளான்டர் (12-20 அங்குலம்) || கிண்ண FRP பிளாண்டர் (16-24 அங்குலம்) || மெட்டல் பிளாண்டர், மல்டிபிள் ஃபினிஷ்ஸ் (8-16 அங்குலம்) || உலோக உருளை ஆலை (8-16 அங்குலம்) || உலோக கியூப் பிளாண்டர் (10-14 அங்குலம்) || உலோக கூம்பு ஆலை (10-18 அங்குலம்) || மெட்டல் பவுல் பிளாண்டர் (12-16 அங்குலம்)",
