    "Teak Wood Planter Box (12-24 in)": "தேக்கு மர நடவு பெட்டி (12-24 அங்குலம்) || பைன்வுட் பிளாண்டர் பாக்ஸ் (12-24 அங்குலம்) || மாம்பழ மரத் தோட்டம், பழமையான (12-24 அங்குலம்) || மர பீப்பாய் ஆலை, அரை வெட்டு (16-20 அங்குலம்) || மர அறுகோண ஆலை (14-18 அங்குலம்) || சிமென்ட் ரவுண்ட் பிளாண்டர், வெற்று சாம்பல் (12-30 அங்குலம்) || சிமெண்ட் அறுகோண ஆலை (12-30 அங்குலம்) || சிமெண்ட் தொட்டி நடுபவர் (12-30 அங்குலம்) || சிமென்ட் கிண்ணத் தோட்டி, பாலிஷ் செய்யப்பட்ட (12-30 அங்குலம்) || தொங்கும் தாவரம், பல வண்ணங்கள் (6-10 அங்குலம்) || தொங்கும் கூடை ஆலை, தென்னை லைன் (8-12 அங்குலம்)",
    "Pinewood Planter Box (12-24 in)": "தொங்கும் கிண்ணத் தோட்டி (6-10 அங்குலம்) || தொங்கும் டோம் பிளாண்டர் (6-8 அங்குலம்) || தண்டவாளம் / பால்கனி பிளாண்டர் (18-24 அங்குலம்) || சொட்டுத் தட்டு (18-30 அங்குலம்) உடன் தண்டவாளத் தொட்டி நடவு",
    "Mango Wood Planter, Rustic (12-24 in)": "சுய-தண்ணீர் ஆலை, பல வண்ணங்கள் (8-14 அங்குலம்)",
    "Wooden Barrel Planter, Half-Cut (16-20 in)": "சுய-நீர்ப்பாசனம் செய்யும் உயரமான சிலிண்டர் ஆலை (10-14 அங்குலம்) || கோகோ ஃபைபர் ரவுண்ட் பாட் (6-10 அங்குலம்) || கோகோ ஃபைபர் தொங்கும் கூடை (8-12 அங்குலம்) || கோகோ ஃபைபர் ஸ்கொயர் பாட் (6-8 அங்குலம்) || பிரம்பு-பாணி வட்ட நடுபவர் (8-12 அங்குலம்) || பிரம்பு-பாணி ஸ்கொயர் பிளாண்டர் (10-14 அங்குலம்)",
    "Wooden Hexagonal Planter (14-18 in)": "பிரம்பு-பாணி உயரமான செடி (14-18 அங்குலம்) || செவ்வக பொன்சாய் தட்டு, பளபளப்பான (6-12 அங்குலம்)",
    "Cement Round Planter, Plain Grey (12-30 in)": "ஓவல் பொன்சாய் பானை, பளபளப்பான (6-10 அங்குலம்) || உருண்டையான பொன்சாய் பானை, பளபளப்பான (6-10 அங்குலம்) || அறுகோண பொன்சாய் பானை, பளபளப்பான (6-8 அங்குலம்)",
    "Cement Hexagon Planter (12-30 in)": "செவ்வக பால்கனி தொட்டி (18-36 அங்குலம்) || குறுகலான பால்கனி தொட்டி (24-30 அங்குலம்) || கிளாசிக் விண்டோ பாக்ஸ் பிளாண்டர் (12-24 அங்குலம்) || ஸ்லேட்டட் ஜன்னல் பாக்ஸ் பிளாண்டர் (18-24 அங்குலம்) || 3-அடுக்கு செங்குத்து டவர் பிளான்டர்",
    "Cement Trough Planter (12-30 in)": "5-அடுக்கு செங்குத்து டவர் பிளான்டர்",
    "Cement Bowl Planter, Polished (12-30 in)": "அடுக்கி வைக்கக்கூடிய வட்ட செங்குத்து செடி",
    "Hanging Planter, Multiple Colours (6-10 in)": "மேல்சுழற்சி செய்யப்பட்ட PET பாட்டில் ஆலை, கையால் வர்ணம் பூசப்பட்டது",
    "Hanging Basket Planter, Coir-Lined (8-12 in)": "அப்சைக்கிள்டு ஆயில் டிரம் பிளாண்டர், ஹாஃப்-கட் || மேல்சுழற்சி பெயிண்ட் டிரம் பிளான்டர்",
    "Hanging Bowl Planter (6-10 in)": "கோகோபீட் பிளாக், 5 கிலோ சுருக்கப்பட்டது",
    "Hanging Dome Planter (6-8 in)": "கோகோபீட் தூள், தளர்வான (5-25 கிலோ) || வெர்மிகுலைட் (1-5கிலோ) || பெர்லைட் (1-5கிலோ) || சிவப்பு மண் (5-25கிலோ) || தோட்டம் / பானை மண் (5-25 கிலோ) || ஆற்று மணல் (25கிலோ) || பண்ணை உரம், தொழு உரம் (25-50கிலோ) || இலை அச்சு (5-25 கிலோ) || Sphagnum Moss (100-500g) || பீட் பாசி (5-20கிலோ) || அரிசி உமி, பச்சை (5-25 கிலோ) || அரிசி உமி, கார்பனைஸ்டு (5-25 கிலோ)",
