    "Coco Chips / Husk Chips (5kg)": "கோகோ சிப்ஸ் / ஹஸ்க் சிப்ஸ் (5 கிலோ) || பொது-நோக்கு பானை கலவை (5-25 கிலோ) || கற்றாழை & சதைப்பற்றுள்ள பானை கலவை (1-5கிலோ) || ஆர்க்கிட் பட்டை கலவை (1-5கிலோ) || பொன்சாய் மண் கலவை (1-5கிலோ) || மண்புழு உரம் (5-50கிலோ) || காய்ந்த மாட்டு சாணம் உரம் (5-50கிலோ) || கோழி எரு (5-50கிலோ) || வேப்பம் பிண்ணாக்கு தூள் (1-25கிலோ) || எலும்பு உணவு (1-25 கிலோ) || பஞ்சகவ்யா (1-5 லிட்டர்) || ஜீவாம்ருதம் செறிவு (1-5 லிட்டர்) || ஆர்கானிக் கம்போஸ்ட் (5-50கிலோ) || கடுகு கேக் (1-25 கிலோ) || கடற்பாசி துகள்கள் (500g-5kg) || யூரியா (1 கிலோ சில்லறை விற்பனை) || டிஏபி, டி-அம்மோனியம் பாஸ்பேட் (1 கிலோ சில்லறை விற்பனை) || MOP, மியூரேட் ஆஃப் பொட்டாஷ் (1 கிலோ சில்லறை விற்பனை) || NPK 19:19:19 (1-25kg) || NPK 20:20:20 (1-25kg) || கால்சியம் நைட்ரேட் (1-25கிலோ) || மெக்னீசியம் சல்பேட், எப்சம் உப்பு (500 கிராம்-5 கிலோ)",
    "General-Purpose Potting Mix (5-25kg)": "நுண்ணூட்டச் சத்து கலவை, சிறுமணி (1-5கிலோ) || ஜிங்க் சல்பேட் (500கிராம்-5கிலோ) || கடற்பாசி சாறு, திரவம் (250ml-1L) || ஹ்யூமிக் அமில திரவம் (250மிலி-1லி) || மீன் குழம்பு திரவம் (250ml-1L) || அமினோ அமில டானிக் (100-500மிலி) || வேர்விடும் / வளர்ச்சி ஹார்மோன் தீர்வு (10-100மிலி)",
    "Cactus & Succulent Potting Mix (1-5kg)": "பூக்கும் மற்றும் பழம்தரும் பூஸ்டர் திரவம் (250ml-1L) || NPK 19:19:19 திரவ உரம் (250ml-1L) || வெர்மிவாஷ் (500மிலி-1லி) || ரைசோபியம் கலாச்சாரம் (200-500 கிராம்) || அசோஸ்பைரில்லம் கலாச்சாரம் (200-500 கிராம்) || பாஸ்பேட் கரைக்கும் பாக்டீரியா, PSB (200-500g) || Mycorrhiza, VAM தடுப்பூசி (250g-1kg)",
