    "Areca Palm": "అరెకా పామ్ || మందార || ఇక్సోరా / జంగిల్ ఫ్లేమ్ || ఒలీండర్ || క్రేప్ జాస్మిన్ నందియార్ వట్టై || బౌగెన్విల్లా || పెరెగ్రినా జత్రోఫా || లాంటానా || బంగారు దిబ్బ దురంత గోల్డెన్ || కార్డినల్ క్రీపర్ ఇపోమియా || కోరల్ వైన్ || పరదా లత || బంగారు వెదురు మణి మూంగిల్ || మేరిగోల్డ్ విత్తనాలు || కాలిఫోర్నియా గసగసాలు || లావెండర్ విత్తనాలు || Loofah Ridge Gourd Seeds || సాదా గుండ్రని టెర్రకోట కుండ || రిమ్డ్ టెర్రకోట పాట్ || రిడ్జ్డ్ / గ్రూవ్డ్ టెర్రకోట పాట్ || గ్లేజ్డ్-రిమ్ టెర్రకోట పాట్ || పెయింటెడ్ టెర్రకోట పాట్ || చెట్టినాడ్-శైలి టెర్రకోట కుండ || టెర్రకోట లాంగ్ టామ్ పాట్ || టెర్రకోట బోన్సాయ్ పాట్ (నిస్సారమైన) || HDPE గ్రో బ్యాగ్ - తెలుపు (UV-పూత) || UV-స్టెబిలైజ్డ్ గ్రో బ్యాగ్స్ || నర్సరీ పాలీబ్యాగులు || రూట్ ట్రైనర్ ట్యూబ్స్ || ప్లగ్/సీడ్లింగ్ ట్రేలు || గాలి కత్తిరింపు కుండలు || ఫ్యాబ్రిక్ గ్రో పాట్స్ || నర్సరీ ప్రో-ట్రేలు || గ్రో బ్యాగ్ స్టాండ్‌లు/హోల్డర్లు || కొబ్బరి పొట్టు కోకో పీట్ ఇటుక || కొబ్బరి కుండల మిశ్రమం || వర్మీకంపోస్ట్ 5కిలోలు || హ్యాండ్ ట్రోవెల్ & వీడర్ సెట్ || సిరామిక్ విండ్ చైమ్ || మోటైన గార్డెన్ స్టేక్ సెట్ || గార్డెన్ గ్నోమ్ || అలంకార ఉర్న్ ప్లాంటర్ || టేబుల్‌టాప్ గార్డెన్ ఫౌంటెన్ || తోట విగ్రహం || సోలార్ గార్డెన్ లైట్ || పక్షుల స్నానం || బర్డ్ ఫీడర్ || అలంకార స్టెప్పింగ్ స్టోన్స్ (4 సెట్) || గార్డెన్ సిగ్నేజ్ బోర్డ్ || ఫెయిరీ గార్డెన్ అనుబంధ సెట్",
