    "Metal Wind Spinner": "మెటల్ విండ్ స్పిన్నర్ || తోట గొట్టం పైపు || గొట్టం రీల్ || గొట్టం నాజిల్/స్ప్రే గన్ || ఇంపాక్ట్/రోటరీ స్ప్రింక్లర్ || మైక్రో స్ప్రింక్లర్లు || ఓవర్ హెడ్ స్ప్రింక్లర్ సిస్టమ్ || నీటిపారుదల నీటి టైమర్ || సబ్మెర్సిబుల్ వాటర్ పంప్ || డ్రిప్ పార్శ్వ పైపు (16మి.మీ) || ఇన్లైన్ డ్రిప్పర్స్ (ప్యాక్) || ఫాగర్/మిస్టింగ్ నాజిల్స్ || నీళ్ళు పోసే దండ || రెయిన్ గన్ || గొట్టం కనెక్టర్లు & కప్లింగ్స్ || డ్రిప్ పార్శ్వ పైపు (12మి.మీ) || ఆన్‌లైన్ డ్రిప్ ఎమిటర్స్ || డ్రిప్ టేప్ || గ్రోమెట్స్/టేక్-ఆఫ్ కనెక్టర్లు || వెంచురి ఫర్టిలైజర్ ఇంజెక్టర్ || స్క్రీన్ ఫిల్టర్ || డిస్క్ ఫిల్టర్ || ప్రెజర్ గేజ్ || గాలి విడుదల వాల్వ్ || ఎండ్ క్యాప్స్ (ప్యాక్) || టీ/ఎల్బో/జాయినర్ ఫిట్టింగ్‌లు (ప్యాక్) || డ్రిప్ స్టేక్స్ (ప్యాక్) || ఫెర్టిగేషన్ ట్యాంక్ || వెదురు పందెం (ప్యాక్) || టమోటా పంజరాలు || ట్రేల్లిస్ నెట్టింగ్ || ప్లాంట్ సపోర్ట్ క్లిప్‌లు || కొబ్బరి తాడు || వైర్ మెష్ సపోర్ట్ || బోన్సాయ్ ట్రైనింగ్ వైర్ (అల్యూమినియం/కాపర్) || క్లైంబింగ్ ప్లాంట్ సపోర్ట్ ఫ్రేమ్ || వెల్క్రో ప్లాంట్ టైస్ || జ్యూట్ ట్వైన్ || ప్లాంట్ సపోర్ట్ రింగ్స్ || ఎస్పాలియర్ వైర్ కిట్ || ప్రచారం వేడి మత్ || కటింగ్ ప్రచారం ట్రేలు || బడ్డింగ్ టేప్ || కంపోస్ట్ థర్మామీటర్ || కంపోస్ట్ టర్నర్ సాధనం || బయోడిగ్రేడబుల్ కంపోస్ట్ సంచులు || ప్లాంట్ లేబుల్స్/మార్కర్స్ (ప్యాక్) || గార్డెన్ పురిబెట్టు || నర్సరీ ప్లాంట్ ట్యాగ్‌లు (ప్యాక్) || కొలిచే స్కూప్",
