    "Garden Apron": "గార్డెన్ అప్రాన్ || మోకాలి ప్యాడ్ || గార్డెన్ ట్రాలీ/కేడీ || మట్టి జల్లెడ || నేల తేమ మీటర్ || నేల pH పరీక్ష కిట్ || నేల థర్మామీటర్ || నెట్ కుండలు || LECA (క్లే పెబుల్స్) || రాక్‌వుల్ క్యూబ్స్ || హైడ్రోపోనిక్ న్యూట్రియంట్ సొల్యూషన్ (A & B) || pH అప్/డౌన్ సొల్యూషన్ || EC/TDS మీటర్ || ఎయిర్ పంప్ & ఎయిర్ స్టోన్ || డీప్ వాటర్ కల్చర్ (DWC) బకెట్ కిట్ || NFT ఛానెల్‌లు || హైడ్రోపోనిక్ రిజర్వాయర్ ట్యాంక్ || హైడ్రోపోనిక్ టవర్ కిట్ || గ్రో స్పాంజ్‌లు/ఒయాసిస్ క్యూబ్స్ || ఫెల్ట్ వర్టికల్ గార్డెన్ పాకెట్స్ || మాడ్యులర్ గ్రీన్ వాల్ ప్యానెల్ || నిలువు ప్లాంటర్ టవర్ || వాల్-మౌంటెడ్ ప్లాంటర్ బ్రాకెట్స్ || లివింగ్ వాల్ ఇరిగేషన్ కిట్ || వర్టికల్ గార్డెన్ ట్రేల్లిస్ ఫ్రేమ్ || స్టాక్ చేయగల ప్లాంటర్ సిస్టమ్ || మాన్యువల్ లాన్ మొవర్ || గ్రాస్ ట్రిమ్మర్/బ్రష్ కట్టర్ || లాన్ టాప్-డ్రెస్సింగ్ ఇసుక || పచ్చిక ఎరువుల స్పైక్స్ || గార్డెన్ బోర్డర్ స్టోన్స్ || లాన్ ఎడ్జింగ్ స్ట్రిప్స్ || స్పైక్డ్ లాన్ ఎరేటర్ || సహజ టర్ఫ్ రోల్స్ || ల్యాండ్‌స్కేప్/వీడ్-బారియర్ ఫ్యాబ్రిక్ || నది గులకరాళ్లు || నల్లని పాలిష్ చేసిన గులకరాళ్లు || వైట్ మార్బుల్ చిప్స్ || రంగుల అలంకార కంకర || కోకో మల్చ్ చిప్స్ || చెక్క బెరడు మల్చ్ || అలంకార లావా రాక్స్ || పిండిచేసిన స్టోన్ గ్రావెల్ మిక్స్ || గ్రీన్ షేడ్ నెట్ (50%) || బ్లాక్ షేడ్ నెట్ || యాంటీ-హెయిల్ నెట్ || బర్డ్ ప్రొటెక్షన్ నెట్ || ఇన్సెక్ట్ ప్రూఫ్ ఆగ్రో నెట్ || ఫ్రాస్ట్ ప్రొటెక్షన్ ఫ్లీస్ కవర్ || ప్లాస్టిక్ మల్చింగ్ ఫిల్మ్",
