    "LED Grow Light": "LED గ్రో లైట్ || స్వీయ-నీరు త్రాగుట ఇండోర్ పాట్ || ఇండోర్ ప్లాంట్ తేమ ట్రే || టెర్రేరియం కంటైనర్ || గాలిని శుద్ధి చేసే ప్లాంట్ స్టాండ్ || తేమ పెబుల్ ట్రే || ఇండోర్ ప్లాంట్ మిస్టింగ్ స్ప్రే బాటిల్ || అలంకారమైన ఇండోర్ ప్లాంట్ స్టాండ్ || స్లో-రిలీజ్ ప్లాంట్ ఫుడ్ స్పైక్‌లు || క్రిమి/బటర్‌ఫ్లై హోటల్ || స్మార్ట్ సాయిల్ మాయిశ్చర్ సెన్సార్ || Wi-Fi ఇరిగేషన్ కంట్రోలర్ || యాప్-ఆధారిత మొక్కల ఆరోగ్య సెన్సార్ || ఆటోమేటిక్ డ్రిప్ ఇరిగేషన్ టైమర్ || మోషన్ సెన్సార్‌తో సోలార్ గార్డెన్ లైట్ || బ్లూటూత్ సాయిల్ టెస్ట్ పరికరం || చైనీస్ మర్రి ఫికస్ బోన్సాయ్ || బన్యన్ బోన్సాయ్ || Bougainvillea బోన్సాయ్ || ఎడారి రోజ్ బోన్సాయ్ అడెనియం || మినీ సక్యూలెంట్ త్రయం || కోకోయిల్ ప్లాంట్ కేర్ గిఫ్ట్ సెట్ || ఫాలెనోప్సిస్ ఆర్చిడ్ || చైనీస్ ఎవర్‌గ్రీన్ (అగ్లోనెమా) || మూగ చెరకు (డిఫెన్‌బాచియా) || హార్ట్‌లీఫ్ ఫిలోడెండ్రాన్ || కలాథియా || బేబీ రబ్బర్ ప్లాంట్ (పెపెరోమియా) || ఫిడిల్ లీఫ్ ఫిగ్ || రబ్బరు మొక్క || జాడే మొక్క || క్రోటన్ || కలబంద || స్థూపాకార స్నేక్ ప్లాంట్ || డబ్బు చెట్టు || మరగుజ్జు గొడుగు చెట్టు (షెఫ్లెరా) || ఆఫ్రికన్ మాస్క్ ప్లాంట్ (అలోకాసియా) || ఏనుగు చెవి (కొలోకాసియా) || స్వర్గం యొక్క తెల్ల పక్షి (స్ట్రెలిట్జియా) || ప్రార్థన మొక్క (మరాంటా) || మార్బుల్ క్వీన్ పోథోస్ || రంగురంగుల రాక్షసుడు || గోల్డెన్ హహ్ని స్నేక్ ప్లాంట్ || రకరకాల స్పైడర్ ప్లాంట్ || ఇంగ్లీష్ ఐవీ || గుండెల స్ట్రింగ్ || ముత్యాల తీగ || బ్లషింగ్ ఫిలోడెండ్రాన్ (ఎరుపు) || స్విస్ చీజ్ ప్లాంట్ (మాన్‌స్టెరా) || పింక్ ప్రిన్సెస్ ఫిలోడెండ్రాన్",
