    "Arrowhead Plant (Syngonium)": "బాణం తల మొక్క (సింగోనియం) || సిబు బ్లూ పోథోస్ || ఆంథూరియం || ఆఫ్రికన్ వైలెట్ || ఫ్లేమింగ్ కాటీ (కలాంచో) || మనీ ప్లాంట్ (వాటర్ కల్చర్) || బాణం తల (నీటి సంస్కృతి) || ఫిలోడెండ్రాన్ (నీటి సంస్కృతి) || అదృష్ట వెదురు || నరాల మొక్క (ఫిట్టోనియా) || బేబీ టియర్స్ (పిలియా) || స్పైక్‌మాస్ (క్లబ్ మోస్) || నెమలి మొక్క (కలాథియా మకోయానా) || పార్లర్ పామ్ || చైనీస్ మనీ ప్లాంట్ (పిలియా పెపెరోమియోయిడ్స్) || ఫిలోడెండ్రాన్ గ్లోరియోసమ్ || క్వీన్ ఆంథూరియం || రంగురంగుల మాన్‌స్టెరా అడాన్సోని || బ్లాక్ గోల్డ్ ఫిలోడెండ్రాన్ (మెలనోక్రిసమ్) || క్రేప్ జాస్మిన్ (నండియార్ వట్టై) || పెరెగ్రినా (జత్రోఫా) || బంగారు దిబ్బ దురంత || కాపర్లీఫ్ (అకాలిఫా) || పర్పుల్ ఫాల్స్ ఎరాంతిమం || క్యారికేచర్ ప్లాంట్ (గ్రాప్టోఫిలమ్) || మేరిగోల్డ్ || కాక్స్‌కాంబ్ (సెలోసియా) || పెటునియా || జిన్నియా || సన్ రోజ్ / మోస్ రోజ్ (పోర్టులాకా) || విన్కా / సదాబహార్ || ఈజిప్షియన్ స్టార్ క్లస్టర్ (పెంటాస్) || మెక్సికన్ పెటునియా (రూలియా) || బ్లాంకెట్ ఫ్లవర్ (గైల్లార్డియా) || దురంత హెడ్జ్ || కాపర్లీఫ్ హెడ్జ్ || అడవి జాస్మిన్ హెడ్జ్ || ఏడుస్తున్న అంజీర ముళ్ళ || వెడెలియా || శాశ్వత వేరుశెనగ || జోసియా గ్రాస్ || జోసెఫ్\\ || మోండో గ్రాస్ || స్పైడర్ ప్లాంట్ (సరిహద్దు ఉపయోగం) || మెక్సికన్ హీథర్ (కుఫియా) || వైట్ ఫ్రంగిపానీ || గుల్మోహర్ / ఫ్లేమ్ ట్రీ || గోల్డెన్ షవర్ ట్రీ || ఇండియన్ కార్క్ ట్రీ || రాణి\\",
