    "Pink Trumpet Tree (Tabebuia)": "పింక్ ట్రంపెట్ ట్రీ (టాబెబుయా) || ఆఫ్రికన్ తులిప్ చెట్టు || అశోక వృక్షం || రాగిపాడ్ / పసుపు పాయిన్సియానా || భారతీయ బాదం || మర్రి చెట్టు || పీపుల్ చెట్టు || రెయిన్ ట్రీ || బెంగాల్ క్లాక్ వైన్ (థన్‌బెర్జియా) || ఆరెంజ్ ట్రంపెట్ వైన్ || కార్డినల్ క్రీపర్ (ఇపోమియా) || బంగారు వెదురు || హెడ్జ్ వెదురు || మగ వెదురు / కలకత్తా వెదురు || దురంత టాపియరీ || ఫికస్ టోపియరీ || కామినీ టాపియరీ || గోల్డెన్ కేన్ పామ్ || కొబ్బరి తాటి || రాయల్ పామ్ || పిగ్మీ ఖర్జూరం || ఫిష్‌టెయిల్ పామ్ || చైనీస్ ఫ్యాన్ పామ్ || మెక్సికన్ ఫ్యాన్ పామ్ (వాషింగ్టోనియా) || చైనీస్ విండ్‌మిల్ పామ్ || సీసా అరచేతి || ట్రయాంగిల్ పామ్ || బిస్మార్క్ పామ్ || సాగో పామ్ (వాణిజ్యం) || మాకర్తుర్ తాటి || లేడీ పామ్ || తాటిపండు || సాగో పామ్ (సైకాడ్) || క్వీన్ సాగో || రంఫ్\\ || అట్ట అరచేతి || చెస్ట్నట్ డియోన్ || జులులాండ్ సైకాడ్ (ఎన్సెఫాలార్టోస్) || జామియా పామ్ (మాక్రోజామియా) || మెక్సికన్ స్నోబాల్ (ఎచెవేరియా) || జీబ్రా ప్లాంట్ (హవోర్తియా) || బుర్రో\\ || బటన్ల స్ట్రింగ్ || లేస్ కలబంద || టార్చ్ కలబంద || పాండా మొక్క || వేలమందికి తల్లి || వేల్ ఫిన్ స్నేక్ ప్లాంట్ || ఏనుగు పొద || ఘోస్ట్ ప్లాంట్",
