    "Century Plant (Agave)": "సెంచరీ ప్లాంట్ (కిత్తలి) || ఫాక్స్‌టైల్ కిత్తలి || పెన్సిల్ కాక్టస్ || ఆఫ్రికన్ మిల్క్ ట్రీ || లివింగ్ స్టోన్స్ (లిథాప్స్) || అరటిపండ్ల తీగ || ఆక్స్ టంగ్ ప్లాంట్ (గ్యాస్టేరియా) || ఎడారి గులాబీ || మూన్‌స్టోన్స్ (పాచిఫైటమ్) || పెరువియన్ ఆపిల్ కాక్టస్ || గోల్డెన్ బారెల్ కాక్టస్ || బన్నీ ఇయర్ కాక్టస్ (ఒపుంటియా) || మూన్ కాక్టస్ || బిషప్\\ || ఓల్డ్ మాన్ కాక్టస్ || క్రిస్మస్ కాక్టస్ || ఎలుక తోక కాక్టస్ || లేడీ ఫింగర్ కాక్టస్ (మామిల్లారియా) || ప్రిక్లీ పియర్ || ఎచెవేరియా టేబుల్ టాప్ || బేబీ రబ్బర్ ప్లాంట్ (టేబుల్ టాప్) || నరాల మొక్క (టేబుల్ టాప్) || గ్లోక్సినియా || చైనీస్ మనీ ప్లాంట్ (టేబుల్ టాప్) || మినీ ఎచెవేరియా || థింబుల్ కాక్టస్ || బేబీ\\ || టేబుల్ ఫెర్న్ (మినీ) || చైనీస్ బన్యన్ బోన్సాయ్ (ఫికస్) || జాడే బోన్సాయ్ || ప్రేమ్నా బోన్సాయ్ || చైనీస్ జునిపెర్ బోన్సాయ్ || డెండ్రోబియం ఆర్చిడ్ || నీలి వంద || మాత్ ఆర్చిడ్ (ఫాలెనోప్సిస్) || కోర్సేజ్ ఆర్చిడ్ (కాట్లేయా) || డ్యాన్స్ లేడీ ఆర్చిడ్ (ఆన్సిడియం) || సింబిడియం ఆర్చిడ్ || ఫిలిప్పైన్ గ్రౌండ్ ఆర్చిడ్ || మొకరా ఆర్చిడ్ || స్కార్లెట్ స్టార్ (గుజ్మానియా) || జ్వలించే కత్తి (వ్రీసియా) || సిల్వర్ వాజ్ ప్లాంట్ (ఎచ్మియా) || బ్లషింగ్ బ్రోమెలియడ్ (నియోరెజిలియా) || స్పానిష్ నాచు (ఎయిర్ ప్లాంట్) || బోస్టన్ ఫెర్న్ || పక్షి\\ || మైడెన్‌హెయిర్ ఫెర్న్ || స్టాగ్హార్న్ ఫెర్న్ || కుందేలు\\",
