    "Silver Lace Fern (Table Fern)": "సిల్వర్ లేస్ ఫెర్న్ (టేబుల్ ఫెర్న్) || ఉష్ణమండల పిచ్చర్ ప్లాంట్ (నెపెంతీస్) || వీనస్ ఫ్లైట్రాప్ || కేప్ సన్డ్యూ || పర్పుల్ పిచ్చర్ ప్లాంట్ (సర్రాసెనియా) || వాటర్ హైసింత్ || నీటి పాలకూర || కాటైల్ (బుల్రష్) || పాపిరస్ || నీటి కలువ || కమలం || ఈల్ గ్రాస్ (వల్లిస్నేరియా) || ఏనుగు చెవి (చెరువు) || హార్ట్‌లీఫ్ ఫిలోడెండ్రాన్ (నిలువు) || బాణం తల (నిలువు) || బోస్టన్ ఫెర్న్ (నిలువు) || నాచు గులాబీ (నిలువు) || స్పైడర్ ప్లాంట్ (గ్రీన్ వాల్) || సంచరిస్తున్న యూదుడు (ట్రేడ్స్‌కాంటియా) || బేబీ రబ్బర్ ప్లాంట్ (గ్రీన్ వాల్) || ఇక్సోరా (టెర్రేస్) || మరగుజ్జు జామ || మడగాస్కర్ డ్రాగన్ ట్రీ (డ్రాకేనా మార్జినాటా) || మినియేచర్ రోజ్ || పచ్చ అలల పెపెరోమియా || ఎచెవేరియా (బాల్కనీ) || వెర్బెనా వెనుకంజలో ఉంది || స్వీడిష్ ఐవీ (ప్లెక్ట్రాంథస్) || మిస్ట్లెటో కాక్టస్ (రిప్సాలిస్) || నిమ్మకాయ || సున్నం || మామిడిపండు || జామ || దానిమ్మ || సీతాఫలం || బొప్పాయి || మల్బరీ || జమైకన్ చెర్రీ / స్ట్రాబెర్రీ ట్రీ || భారతీయ జుజుబ్ || మరగుజ్జు కొబ్బరి || నక్షత్ర ఫలం || పాషన్ ఫ్రూట్ || మైనపు యాపిల్ || స్ట్రాబెర్రీ || అంజీర్ || డ్రాగన్ ఫ్రూట్ || ద్రాక్ష || సపోటా / చీకూ || జాక్‌ఫ్రూట్ || తులసి",
