    "Mint": "పుదీనా || కొత్తిమీర || ఒరేగానో || రోజ్మేరీ || థైమ్ || పవిత్ర తులసి (తులసి) || బిట్టర్స్ రాజు (నిలవెంబు) || గోటు కోల (వల్లరై) || కలబంద (ఔషధ) || ఇండియన్ గూస్బెర్రీ (ఉసిరికాయ) || అశ్వగంధ || వేప || మలబార్ గింజ (అడతోడై) || నిమ్మకాయ || గులాబీ సువాసనగల జెరేనియం || లావెండర్ || వెటివర్ || నల్ల మిరియాలు || అల్లం || పసుపు || కరివేపాకు || దాల్చిన చెక్క || లవంగం || తులసి || బేల్ / బిల్వ || పీపాల్ (పవిత్రం) || కమలం (పవిత్రమైనది) || అరేబియన్ జాస్మిన్ || చంపక్ || ఇక్సోరా (సీతాకోకచిలుక) || లాంటానా (సీతాకోకచిలుక) || ఇండియన్ బర్త్‌వోర్ట్ (అరిస్టోలోచియా) || ట్రాపికల్ మిల్క్‌వీడ్ || కోట్ బటన్లు (ట్రైడాక్స్) || కాస్మోస్ || పొద్దుతిరుగుడు పువ్వు || భారతీయ పగడపు చెట్టు || సిల్వర్ ఓక్ || బాటిల్ బ్రష్ || అరేబియన్ జాస్మిన్ (సువాసన) || ట్యూబెరోస్ || రాత్రి వికసించే మల్లెపూలు || ఫ్రాంగిపాని (ఎరుపు) || నాస్టూర్టియం || రోసెల్లే || పాన్సీ || సరుగుడు / బీచ్ షీ-ఓక్ || స్క్రూపైన్ || క్రౌన్ ఫ్లవర్ || బీచ్ మార్నింగ్ గ్లోరీ",
