    "Beach Cabbage (Scaevola)": "బీచ్ క్యాబేజీ (స్కేవోలా) || పోర్టియా చెట్టు || అడవి మల్లె (కోస్టల్) || మడగాస్కర్ బాదం || అర్జునా || బహెడ || హరితకి || కరంజ్ / పొంగమియా || మహోగని || ఆఫ్రికన్ మహోగని || తెల్ల దేవదారు || ఇండియన్ మహోగని (టూన్) || కర్పూరం చెట్టు || జామున్ || చింతపండు || మహువా || బకుల్ || రుద్రాక్ష || పలాష్ / అడవి జ్వాల || పట్టు పత్తి చెట్టు || సముద్ర మందార || అలెగ్జాండ్రియన్ లారెల్ || నిజమైన అశోకా || జకరందా || కదంబ || పుత్రంజీవ || పింక్ షవర్ ట్రీ || ఆర్కిడ్ ట్రీ (పర్పుల్) || ఆర్కిడ్ చెట్టు (తెలుపు) || పసుపు తబెబుయా || వెండి ట్రంపెట్ చెట్టు || తెల్ల ట్రంపెట్ చెట్టు || ఫిరంగి చెట్టు || సాసేజ్ ట్రీ || ఏడ్చే అత్తి చెట్టు || ఇండియన్ లారెల్ ఫిగ్ || ఫికస్ పాండా || మాగ్నోలియా || ఆస్ట్రేలియన్ పైన్ || నార్ఫోక్ ఐలాండ్ పైన్ || కుక్ పైన్ || బాబాబ్ || మంకీ పజిల్ ట్రీ || డ్రాగన్ బ్లడ్ ట్రీ || అగ్లోనెమా రెడ్ || అగ్లోనెమా సిల్వర్ బే || ఫిలోడెండ్రాన్ Xanadu || ఫిలోడెండ్రాన్ సెల్లౌమ్ || మాన్‌స్టెరా డెలిసియోసా || డిఫెన్‌బాచియా కామిల్లె",
