    "Dracaena Marginata": "డ్రాకేనా మార్జినాటా || డ్రాకేనా కాంపాక్టా || డ్రాకేనా సాంగ్ ఆఫ్ ఇండియా || జమైకాలోని డ్రాకేనా సాంగ్ || కార్డిలైన్ రెడ్ || కార్డిలైన్ గ్రీన్ (టి ప్లాంట్) || అకాలిఫా గ్రీన్ || మింగ్ అరాలియా || రకరకాల అరలియా || ఆకుపచ్చ అరాలియా || రంగురంగుల షెఫ్లెరా || గ్రీన్ షెఫ్లెరా || దురంత గోల్డెన్ ఎడ్జ్ || రకరకాల దురంత || కామిని (ఆరెంజ్ జాస్మిన్) || గార్డెనియా || పసుపు గంటలు (టెకోమా) || ఆరెంజ్ టెకోమా || పసుపు అల్లమందా || ఊదా రంగు అల్లమందా || పింక్ ముస్సేండా || తెల్ల ముస్సేండా || ఫైర్‌బుష్ (హమేలియా పాటెన్స్) || ఫైర్‌క్రాకర్ ప్లాంట్ (రసేలియా) || బ్లూ ప్లంబాగో || వైట్ ప్లంబాగో || వైల్డ్ జాస్మిన్ (క్లెరోడెండ్రమ్ ఇనెర్మ్) || జ్వలించే గ్లోరీబోవర్ || మెక్సికన్ పెటునియా (పొడవైన) || మరగుజ్జు క్రాసాండ్రా || ఫిలిప్పైన్ వైలెట్ (బార్లేరియా) || రెడ్ పెంటాస్ || పింక్ పెంటాస్ || తెల్ల పెంటలు || పసుపు ఇక్సోరా || మరగుజ్జు ఇక్సోరా || ఎర్ర మందార || పసుపు మందార || రంగురంగుల మందార || స్వర్గపు పక్షి || లోరోపెటలం (చైనీస్ ఫ్రింజ్ ఫ్లవర్) || భారతీయ హౌథ్రోన్ || బోట్ లిల్లీ (రియో త్రివర్ణ) || సంచరిస్తున్న యూదుడు (జెబ్రినా) || Red Alternanthera || పసుపు ప్రత్యామ్నాయం || గ్రీన్ ఆల్టర్నాంథెరా || బ్లడ్లీఫ్ (ఐరెసిన్) || ఆస్పరాగస్ ఫెర్న్ || ఫాక్స్ టైల్ ఫెర్న్",
