    "Tomato Seeds": "టమోటా విత్తనాలు || వంకాయ (వంకాయ) విత్తనాలు || బెండకాయ (భిండి) విత్తనాలు || మిరప గింజలు || క్యాబేజీ విత్తనాలు || కాలీఫ్లవర్ విత్తనాలు || దోసకాయ గింజలు || పొట్లకాయ గింజలు || చేదు పొట్లకాయ గింజలు || గుమ్మడి గింజలు || క్యారెట్ విత్తనాలు || ముల్లంగి గింజలు || బచ్చలికూర (పాలక్) విత్తనాలు || మెంతి (మేతి) విత్తనాలు || ఉల్లిపాయ గింజలు || ఫ్రెంచ్ బీన్ గింజలు || పచ్చి బఠానీ గింజలు || క్యాప్సికమ్ విత్తనాలు || పొట్లకాయ గింజలు || బూడిద పొట్లకాయ గింజలు || జిన్నియా విత్తనాలు || కాస్మోస్ సీడ్స్ || పెటునియా విత్తనాలు || పొద్దుతిరుగుడు విత్తనాలు || బాల్సమ్ విత్తనాలు || పోర్టులాకా విత్తనాలు || విన్కా విత్తనాలు || డయాంథస్ విత్తనాలు || ఆస్టర్ విత్తనాలు || గైలార్డియా విత్తనాలు || సెలోసియా విత్తనాలు || తులసి (తులసి) గింజలు || కొత్తిమీర గింజలు || పుదీనా గింజలు || అజ్వైన్ విత్తనాలు || మెంతులు గింజలు || నిమ్మకాయ గింజలు || బొప్పాయి గింజలు || పుచ్చకాయ గింజలు || సీతాఫలం గింజలు || జామ గింజలు || నిమ్మ గింజలు || ముల్లంగి మైక్రోగ్రీన్ విత్తనాలు || సన్‌ఫ్లవర్ మైక్రోగ్రీన్ సీడ్స్ || మెంతి మైక్రోగ్రీన్ విత్తనాలు || ఆవాలు మైక్రోగ్రీన్ సీడ్స్ || బ్రోకలీ మైక్రోగ్రీన్ సీడ్స్ || బెర్ముడా గ్రాస్ సీడ్ || దూబ్ గ్రాస్ సీడ్ || రైగ్రాస్ సీడ్",
