    "Maize Fodder Seed": "మొక్కజొన్న మేత విత్తనం || జొన్న మేత విత్తనం || లూసర్న్ (అల్ఫాల్ఫా) విత్తనం || ఆవుపేడ మేత విత్తనం || అశ్వగంధ విత్తనం || ఇసాబ్గోల్ (సైలియం) విత్తనం || తులసి విత్తనం (ఔషధ శ్రేణి) || కాలే విత్తనాలు || బ్రోకలీ విత్తనాలు || పాలకూర గింజలు || సొరకాయ గింజలు || బెల్ పెప్పర్ విత్తనాలు || గుల్మోహర్ విత్తనాలు || వేప గింజలు || మందార విత్తనాలు || Bougainvillea విత్తనాలు || అమల్టాస్ విత్తనాలు || సాదా గుండ్రని టెర్రకోట పాట్ (4-24 అంగుళాలు) || రిమ్డ్ టెర్రకోట పాట్ (4-24 అంగుళాలు) || రిడ్జ్డ్ / గ్రూవ్డ్ టెర్రకోట పాట్ (4-24 అంగుళాలు) || గ్లేజ్డ్-రిమ్ టెర్రకోట పాట్ (4-24 అంగుళాలు) || పెయింటెడ్ టెర్రకోట కుండ, వర్గీకరించబడిన రంగులు (4-24 అంగుళాలు) || చెట్టినాడ్-శైలి టెర్రకోట పాట్ (4-24 అంగుళాలు) || టెర్రకోట లాంగ్ టామ్ పాట్ (6-24 అంగుళాలు) || టెర్రకోట బోన్సాయ్ కుండ, నిస్సార (4-14 అంగుళాలు) || షట్కోణ టెర్రకోట ప్లాంటర్ (8-14 అంగుళాలు) || స్థూపాకార టెర్రకోట ప్లాంటర్ (8-16 అంగుళాలు) || టెర్రకోట దీర్ఘచతురస్రాకార ట్రఫ్ (12-24 అంగుళాలు) || శంఖాకార టెర్రకోట ప్లాంటర్ (8-12 అంగుళాలు) || మెరుస్తున్న సిరామిక్ కుండ, బహుళ ముగింపులు (6-12 అంగుళాలు) || రెండు-టోన్ గ్లేజ్డ్ సిరామిక్ పాట్ (6-12 అంగుళాలు) || ఓవల్ గ్లేజ్డ్ సిరామిక్ ప్లాంటర్ (8-12 అంగుళాలు) || షట్కోణ గ్లేజ్డ్ సిరామిక్ పాట్ (6-10 అంగుళాలు) || సిరామిక్ సిలిండర్ ప్లాంటర్, గ్లేజ్డ్ (8-14 అంగుళాలు) || సిరామిక్ బౌల్ ప్లాంటర్, గ్లేజ్డ్ (8-12 అంగుళాలు) || గుండ్రని ప్లాస్టిక్ కుండ, బహుళ రంగులు (4-18 అంగుళాలు) || స్క్వేర్ ప్లాస్టిక్ ప్లాంటర్, బహుళ రంగులు (6-12 అంగుళాలు) || ఓవల్ ప్లాస్టిక్ ప్లాంటర్ (8-14 అంగుళాలు) || దీర్ఘచతురస్రాకార ప్లాస్టిక్ ట్రౌ ప్లాంటర్ (12-24 అంగుళాలు) || టాపర్డ్ ప్లాస్టిక్ పాట్ (8-14 అంగుళాలు) || ఫైబర్-రీన్ఫోర్స్డ్ ప్లాంటర్, బహుళ ముగింపులు (10-24 అంగుళాలు) || శంఖాకార FRP ప్లాంటర్ (12-24 in) || స్థూపాకార FRP ప్లాంటర్ (12-30 in) || క్యూబ్ FRP ప్లాంటర్ (12-20 అంగుళాలు) || బౌల్ FRP ప్లాంటర్ (16-24 అంగుళాలు) || మెటల్ ప్లాంటర్, బహుళ ముగింపులు (8-16 అంగుళాలు) || మెటల్ స్థూపాకార ప్లాంటర్ (8-16 అంగుళాలు) || మెటల్ క్యూబ్ ప్లాంటర్ (10-14 అంగుళాలు) || మెటల్ కోనికల్ ప్లాంటర్ (10-18 అంగుళాలు) || మెటల్ బౌల్ ప్లాంటర్ (12-16 అంగుళాలు)",
