    "Areca Palm": "ಅರೆಕಾ ಪಾಮ್ || ದಾಸವಾಳ || ಇಕ್ಸೋರಾ / ಜಂಗಲ್ ಫ್ಲೇಮ್ || ಒಲಿಯಂಡರ್ || ಕ್ರೇಪ್ ಜಾಸ್ಮಿನ್ ನಂದಿಯಾರ್ ವಟ್ಟೈ || ಬೌಗೆನ್ವಿಲ್ಲಾ || ಪೆರೆಗ್ರಿನಾ ಜತ್ರೋಫಾ || ಲಂಟಾನ || ಚಿನ್ನದ ದಿಬ್ಬ ದುರಂತ ಸುವರ್ಣ || ಕಾರ್ಡಿನಲ್ ಕ್ರೀಪರ್ ಇಪೋಮಿಯಾ || ಹವಳದ ಬಳ್ಳಿ || ತೆರೆ ಬಳ್ಳಿ || ಚಿನ್ನದ ಬಿದಿರು ಮಣಿ ಮೂಂಗಿಲ್ || ಮಾರಿಗೋಲ್ಡ್ ಬೀಜಗಳು || ಕ್ಯಾಲಿಫೋರ್ನಿಯಾ ಗಸಗಸೆ ಬೀಜಗಳು || ಲ್ಯಾವೆಂಡರ್ ಬೀಜಗಳು || ಲೂಫಾ ರಿಡ್ಜ್ ಸೋರೆಕಾಯಿ ಬೀಜಗಳು || ಸರಳ ಸುತ್ತಿನ ಟೆರಾಕೋಟಾ ಮಡಕೆ || ರಿಮ್ಡ್ ಟೆರಾಕೋಟಾ ಪಾಟ್ || ರಿಡ್ಜ್ಡ್ / ಗ್ರೂವ್ಡ್ ಟೆರಾಕೋಟಾ ಪಾಟ್ || ಮೆರುಗು-ರಿಮ್ ಟೆರಾಕೋಟಾ ಪಾಟ್ || ಬಣ್ಣಿಸಿದ ಟೆರಾಕೋಟಾ ಮಡಕೆ || ಚೆಟ್ಟಿನಾಡು-ಶೈಲಿಯ ಟೆರಾಕೋಟಾ ಪಾಟ್ || ಟೆರಾಕೋಟಾ ಲಾಂಗ್ ಟಾಮ್ ಪಾಟ್ || ಟೆರಾಕೋಟಾ ಬೋನ್ಸೈ ಪಾಟ್ (ಆಳ) || HDPE ಗ್ರೋ ಬ್ಯಾಗ್ - ಬಿಳಿ (UV-ಲೇಪಿತ) || ಯುವಿ-ಸ್ಟೆಬಿಲೈಸ್ಡ್ ಗ್ರೋ ಬ್ಯಾಗ್ಸ್ || ನರ್ಸರಿ ಪಾಲಿಬ್ಯಾಗ್‌ಗಳು || ರೂಟ್ ಟ್ರೈನರ್ ಟ್ಯೂಬ್ಸ್ || ಪ್ಲಗ್/ಮೊಳಕೆ ತಟ್ಟೆಗಳು || ಏರ್-ಪ್ರೂನಿಂಗ್ ಮಡಕೆಗಳು || ಫ್ಯಾಬ್ರಿಕ್ ಗ್ರೋ ಪಾಟ್ಸ್ || ನರ್ಸರಿ ಪ್ರೊ-ಟ್ರೇಗಳು || ಗ್ರೋ ಬ್ಯಾಗ್ ಸ್ಟ್ಯಾಂಡ್‌ಗಳು/ಹೋಲ್ಡರ್ಸ್ || ತೆಂಗಿನ ಸಿಪ್ಪೆ ಕೊಕೊ ಪೀಟ್ ಇಟ್ಟಿಗೆ || ತೆಂಗಿನಕಾಯಿ ಪಾಟಿಂಗ್ ಮಿಕ್ಸ್ || ವರ್ಮಿಕಾಂಪೋಸ್ಟ್ 5 ಕೆಜಿ || ಹ್ಯಾಂಡ್ ಟ್ರೋವೆಲ್ & ವೀಡರ್ ಸೆಟ್ || ಸೆರಾಮಿಕ್ ವಿಂಡ್ ಚೈಮ್ || ಹಳ್ಳಿಗಾಡಿನ ಗಾರ್ಡನ್ ಸ್ಟಾಕ್ ಸೆಟ್ || ಗಾರ್ಡನ್ ಗ್ನೋಮ್ || ಅಲಂಕಾರಿಕ ಕಲಶ ಸ್ಥಾವರ || ಟೇಬಲ್ಟಾಪ್ ಗಾರ್ಡನ್ ಫೌಂಟೇನ್ || ಉದ್ಯಾನ ಪ್ರತಿಮೆ || ಸೋಲಾರ್ ಗಾರ್ಡನ್ ಲೈಟ್ || ಪಕ್ಷಿ ಸ್ನಾನ || ಬರ್ಡ್ ಫೀಡರ್ || ಅಲಂಕಾರಿಕ ಮೆಟ್ಟಿಲುಗಳು (4 ರ ಸೆಟ್) || ಗಾರ್ಡನ್ ಸಿಗ್ನೇಜ್ ಬೋರ್ಡ್ || ಫೇರಿ ಗಾರ್ಡನ್ ಪರಿಕರಗಳ ಸೆಟ್",
