    "Metal Wind Spinner": "ಮೆಟಲ್ ವಿಂಡ್ ಸ್ಪಿನ್ನರ್ || ಗಾರ್ಡನ್ ಮೆದುಗೊಳವೆ ಪೈಪ್ || ಹೋಸ್ ರೀಲ್ || ಮೆದುಗೊಳವೆ ನಳಿಕೆ/ಸ್ಪ್ರೇ ಗನ್ || ಇಂಪ್ಯಾಕ್ಟ್/ರೋಟರಿ ಸ್ಪ್ರಿಂಕ್ಲರ್ || ಮೈಕ್ರೋ ಸ್ಪ್ರಿಂಕ್ಲರ್ಸ್ || ಓವರ್ಹೆಡ್ ಸ್ಪ್ರಿಂಕ್ಲರ್ ಸಿಸ್ಟಮ್ || ನೀರಾವರಿ ನೀರಿನ ಟೈಮರ್ || ಸಬ್ಮರ್ಸಿಬಲ್ ವಾಟರ್ ಪಂಪ್ || ಡ್ರಿಪ್ ಲ್ಯಾಟರಲ್ ಪೈಪ್ (16mm) || ಇನ್‌ಲೈನ್ ಡ್ರಿಪ್ಪರ್‌ಗಳು (ಪ್ಯಾಕ್) || ಫೋಗರ್/ಮಿಸ್ಟಿಂಗ್ ನಳಿಕೆಗಳು || ನೀರುಣಿಸುವ ದಂಡ || ರೈನ್ ಗನ್ || ಮೆದುಗೊಳವೆ ಕನೆಕ್ಟರ್ಸ್ & ಕಪ್ಲಿಂಗ್ಸ್ || ಡ್ರಿಪ್ ಲ್ಯಾಟರಲ್ ಪೈಪ್ (12ಮಿಮೀ) || ಆನ್‌ಲೈನ್ ಹನಿ ಹೊರಸೂಸುವವರು || ಡ್ರಿಪ್ ಟೇಪ್ || ಗ್ರೊಮೆಟ್ಸ್/ಟೇಕ್-ಆಫ್ ಕನೆಕ್ಟರ್ಸ್ || ವೆಂಚುರಿ ರಸಗೊಬ್ಬರ ಇಂಜೆಕ್ಟರ್ || ಪರದೆಯ ಫಿಲ್ಟರ್ || ಡಿಸ್ಕ್ ಫಿಲ್ಟರ್ || ಒತ್ತಡ ಮಾಪಕ || ಏರ್ ಬಿಡುಗಡೆ ಕವಾಟ || ಎಂಡ್ ಕ್ಯಾಪ್ಸ್ (ಪ್ಯಾಕ್) || ಟೀ/ಎಲ್ಬೋ/ಜಾಯಿನರ್ ಫಿಟ್ಟಿಂಗ್‌ಗಳು (ಪ್ಯಾಕ್) || ಡ್ರಿಪ್ ಸ್ಟೇಕ್ಸ್ (ಪ್ಯಾಕ್) || ಫರ್ಟಿಗೇಶನ್ ಟ್ಯಾಂಕ್ || ಬಿದಿರಿನ ಹಕ್ಕನ್ನು (ಪ್ಯಾಕ್) || ಟೊಮೆಟೊ ಪಂಜರಗಳು || ಟ್ರೆಲ್ಲಿಸ್ ನೆಟಿಂಗ್ || ಸಸ್ಯ ಬೆಂಬಲ ಕ್ಲಿಪ್ಗಳು || ಕಾಯರ್ ಹಗ್ಗ || ವೈರ್ ಮೆಶ್ ಬೆಂಬಲ || ಬೋನ್ಸೈ ಟ್ರೈನಿಂಗ್ ವೈರ್ (ಅಲ್ಯೂಮಿನಿಯಂ/ತಾಮ್ರ) || ಕ್ಲೈಂಬಿಂಗ್ ಪ್ಲಾಂಟ್ ಸಪೋರ್ಟ್ ಫ್ರೇಮ್ || ವೆಲ್ಕ್ರೋ ಪ್ಲಾಂಟ್ ಟೈಸ್ || ಹಲಸಿನ ಹುರಿ || ಸಸ್ಯ ಬೆಂಬಲ ಉಂಗುರಗಳು || ಎಸ್ಪಾಲಿಯರ್ ವೈರ್ ಕಿಟ್ || ಪ್ರಸರಣ ಶಾಖ ಚಾಪೆ || ಕತ್ತರಿಸುವ ಪ್ರಸರಣ ತಟ್ಟೆಗಳು || ಬಡ್ಡಿಂಗ್ ಟೇಪ್ || ಕಾಂಪೋಸ್ಟ್ ಥರ್ಮಾಮೀಟರ್ || ಕಾಂಪೋಸ್ಟ್ ಟರ್ನರ್ ಟೂಲ್ || ಜೈವಿಕ ವಿಘಟನೀಯ ಕಾಂಪೋಸ್ಟ್ ಚೀಲಗಳು || ಸಸ್ಯದ ಲೇಬಲ್‌ಗಳು/ಗುರುತುಗಳು (ಪ್ಯಾಕ್) || ಗಾರ್ಡನ್ ಟ್ವೈನ್ || ನರ್ಸರಿ ಪ್ಲಾಂಟ್ ಟ್ಯಾಗ್‌ಗಳು (ಪ್ಯಾಕ್) || ಅಳತೆ ಸ್ಕೂಪ್",
