    "Garden Apron": "ಗಾರ್ಡನ್ ಏಪ್ರನ್ || ಮೊಣಕಾಲು ಪ್ಯಾಡ್ || ಗಾರ್ಡನ್ ಟ್ರಾಲಿ/ಕ್ಯಾಡಿ || ಮಣ್ಣಿನ ಜರಡಿ || ಮಣ್ಣಿನ ತೇವಾಂಶ ಮಾಪಕ || ಮಣ್ಣಿನ pH ಪರೀಕ್ಷಾ ಕಿಟ್ || ಮಣ್ಣಿನ ಥರ್ಮಾಮೀಟರ್ || ನಿವ್ವಳ ಮಡಕೆಗಳು || LECA (ಕ್ಲೇ ಪೆಬಲ್ಸ್) || ರಾಕ್ವೂಲ್ ಘನಗಳು || ಹೈಡ್ರೋಪೋನಿಕ್ ನ್ಯೂಟ್ರಿಯೆಂಟ್ ಪರಿಹಾರ (A & B) || pH ಅಪ್/ಡೌನ್ ಪರಿಹಾರ || EC/TDS ಮೀಟರ್ || ಏರ್ ಪಂಪ್ & ಏರ್ ಸ್ಟೋನ್ || ಡೀಪ್ ವಾಟರ್ ಕಲ್ಚರ್ (DWC) ಬಕೆಟ್ ಕಿಟ್ || NFT ಚಾನೆಲ್‌ಗಳು || ಹೈಡ್ರೋಪೋನಿಕ್ ರಿಸರ್ವಾಯರ್ ಟ್ಯಾಂಕ್ || ಹೈಡ್ರೋಪೋನಿಕ್ ಟವರ್ ಕಿಟ್ || ಗ್ರೋ ಸ್ಪಂಜುಗಳು/ಓಯಸಿಸ್ ಘನಗಳು || ಫೆಲ್ಟ್ ವರ್ಟಿಕಲ್ ಗಾರ್ಡನ್ ಪಾಕೆಟ್ಸ್ || ಮಾಡ್ಯುಲರ್ ಗ್ರೀನ್ ವಾಲ್ ಪ್ಯಾನಲ್ || ವರ್ಟಿಕಲ್ ಪ್ಲಾಂಟರ್ ಟವರ್ || ವಾಲ್-ಮೌಂಟೆಡ್ ಪ್ಲಾಂಟರ್ ಬ್ರಾಕೆಟ್ಸ್ || ಲಿವಿಂಗ್ ವಾಲ್ ನೀರಾವರಿ ಕಿಟ್ || ವರ್ಟಿಕಲ್ ಗಾರ್ಡನ್ ಟ್ರೆಲ್ಲಿಸ್ ಫ್ರೇಮ್ || ಸ್ಟ್ಯಾಕ್ ಮಾಡಬಹುದಾದ ಪ್ಲಾಂಟರ್ ಸಿಸ್ಟಮ್ || ಕೈಯಿಂದ ಲಾನ್ ಮೊವರ್ || ಹುಲ್ಲು ಟ್ರಿಮ್ಮರ್/ಬ್ರಷ್ ಕಟ್ಟರ್ || ಲಾನ್ ಟಾಪ್-ಡ್ರೆಸಿಂಗ್ ಸ್ಯಾಂಡ್ || ಟರ್ಫ್ ರಸಗೊಬ್ಬರ ಸ್ಪೈಕ್ಗಳು ​​|| ಗಾರ್ಡನ್ ಬಾರ್ಡರ್ ಸ್ಟೋನ್ಸ್ || ಲಾನ್ ಅಂಚು ಪಟ್ಟಿಗಳು || ಮೊನಚಾದ ಲಾನ್ ಏರೇಟರ್ || ನೈಸರ್ಗಿಕ ಟರ್ಫ್ ರೋಲ್ಸ್ || ಲ್ಯಾಂಡ್‌ಸ್ಕೇಪ್/ವೀಡ್-ಬ್ಯಾರಿಯರ್ ಫ್ಯಾಬ್ರಿಕ್",
    "Kneeling Pad": "ನದಿಯ ಉಂಡೆಗಳು || ಕಪ್ಪು ಪಾಲಿಶ್ ಮಾಡಿದ ಉಂಡೆಗಳು || ವೈಟ್ ಮಾರ್ಬಲ್ ಚಿಪ್ಸ್ || ಬಣ್ಣದ ಅಲಂಕಾರದ ಜಲ್ಲಿ || ಕೊಕೊ ಮಲ್ಚ್ ಚಿಪ್ಸ್ || ಮರದ ತೊಗಟೆ ಮಲ್ಚ್ || ಅಲಂಕಾರಿಕ ಲಾವಾ ಶಿಲೆಗಳು || ಪುಡಿಮಾಡಿದ ಕಲ್ಲು ಜಲ್ಲಿ ಮಿಶ್ರಣ || ಹಸಿರು ಶೇಡ್ ನೆಟ್ (50%) || ಕಪ್ಪು ಛಾಯೆ ನೆಟ್ || ಆಲಿಕಲ್ಲು ವಿರೋಧಿ ನೆಟ್ || ಪಕ್ಷಿ ಸಂರಕ್ಷಣಾ ಜಾಲ || ಕೀಟ-ನಿರೋಧಕ ಆಗ್ರೋ ನೆಟ್ || ಫ್ರಾಸ್ಟ್ ಪ್ರೊಟೆಕ್ಷನ್ ಫ್ಲೀಸ್ ಕವರ್ || ಪ್ಲಾಸ್ಟಿಕ್ ಮಲ್ಚಿಂಗ್ ಫಿಲ್ಮ್",
