    "Green Shade Net (75%)": "ವಾತಾಯನ ಜಾಲ || ಶೇಡ್ ಕ್ಲಾತ್ ಕ್ಲಿಪ್ಸ್ (ಪ್ಯಾಕ್) || ಪಾಲಿ ಫಿಲ್ಮ್ ರಿಪೇರಿ ಟೇಪ್ || ಹಸಿರುಮನೆ ಸ್ಟ್ರಕ್ಚರಲ್ ಫಿಟ್ಟಿಂಗ್‌ಗಳು (ಪ್ಯಾಕ್) || ಸ್ಮಾರ್ಟ್ ಹಸಿರುಮನೆ ಹವಾಮಾನ ನಿಯಂತ್ರಕ || ನೆರಳಿನ ಮನೆ ನೆಟಿಂಗ್ ರೋಲ್ || ಜಿಗುಟಾದ ಕೀಟ ಬಲೆಗಳು (ಪ್ಯಾಕ್) || ಫೆರೋಮೋನ್ ಲೂರ್ಸ್ (ಪ್ಯಾಕ್) || ಬರ್ಡ್ ಸ್ಪೈಕ್ಸ್ || ಅಲ್ಟ್ರಾಸಾನಿಕ್ ಕೀಟ ನಿವಾರಕ || ಇಲಿ ಬಲೆಗಳು || ಸೊಳ್ಳೆ ಲಾರ್ವಿಸೈಡ್ ಡಂಕ್ಸ್ || ಹಣ್ಣಿನ ನೊಣ ಬಲೆಗಳು || ಇರುವೆ ಬೆಟ್ ಸ್ಟೇಷನ್ಸ್ (ಪ್ಯಾಕ್) || ಸಸ್ಯ ಪ್ಯಾಕೇಜಿಂಗ್ ಪೆಟ್ಟಿಗೆಗಳು (ಪ್ಯಾಕ್) || ನರ್ಸರಿ ಪಾಲಿ ಸ್ಲೀವ್ಸ್ (ಪ್ಯಾಕ್) || ಬಬಲ್ ವ್ರ್ಯಾಪ್ (ಪ್ಲಾಂಟ್ ಶಿಪ್ಪಿಂಗ್) || ಸುಕ್ಕುಗಟ್ಟಿದ ಸಸ್ಯ ಸಾರಿಗೆ ಪೆಟ್ಟಿಗೆಗಳು (ಪ್ಯಾಕ್) || ಸೆಣಬು ಪ್ಯಾಕೇಜಿಂಗ್ ಚೀಲಗಳು (ಪ್ಯಾಕ್) || ಪೇಪರ್ ಸೀಡ್ ಪ್ಯಾಕೆಟ್‌ಗಳು (ಪ್ಯಾಕ್) || ಗಿಡಗಳಿಗೆ ಗಿಫ್ಟ್-ವ್ರ್ಯಾಪ್ ಸ್ಲೀವ್ಸ್ (ಪ್ಯಾಕ್) || ಬ್ರಾಂಡೆಡ್ ನರ್ಸರಿ ಕ್ಯಾರಿ ಬ್ಯಾಗ್ಸ್ (ಪ್ಯಾಕ್) || ಬಂಡಲಿಂಗ್ ಟ್ವೈನ್ || ಖಾಲಿ ಸಸ್ಯ ಲೇಬಲ್‌ಗಳು (ಪ್ಯಾಕ್) || ಜಲನಿರೋಧಕ ಮಾರ್ಕರ್ ಪೆನ್ನುಗಳು (ಪ್ಯಾಕ್) || ಗ್ರಾಫ್ಟಿಂಗ್ ರಬ್ಬರ್ ಬ್ಯಾಂಡ್ಸ್ (ಪ್ಯಾಕ್) || ನರ್ಸರಿ ರೆಕಾರ್ಡ್ ಟ್ಯಾಗ್‌ಗಳು (ಪ್ಯಾಕ್) || ಜಿಪ್ ಟೈಸ್ (ಪ್ಯಾಕ್) || ಸ್ಟಾಕಿಂಗ್ (ಪ್ಯಾಕ್) ಗೆ ಕೇಬಲ್ ಟೈಸ್ || ನರ್ಸರಿ ಟ್ರೇ ಕ್ಲೀನಿಂಗ್ ಬ್ರಷ್ || ಬಿಸಾಡಬಹುದಾದ ನೈಟ್ರೈಲ್ ಕೈಗವಸುಗಳು (ಪ್ಯಾಕ್) || ಮರೆಮಾಚುವಿಕೆ/ಲೇಬಲಿಂಗ್ ಟೇಪ್ || ನರ್ಸರಿ ಸಾರಿಗೆ ಪೆಟ್ಟಿಗೆಗಳು || ಗಿಡ-ಸಾಗಿಸುವ ಟ್ರಾಲಿ || ನರ್ಸರಿ ಸ್ಟೇಜಿಂಗ್ ಬೆಂಚ್/ಟೇಬಲ್ || ಬೆಲೆ ಟ್ಯಾಗ್ ಹೋಲ್ಡರ್ಸ್/ಸೈನೇಜ್ (ಪ್ಯಾಕ್) || ಕೀಟ ಭೂತಗನ್ನಡಿ || ಗಾರ್ಡನ್ ಡೈರಿ/ಪ್ಲಾನರ್ || ಬಹುಪಯೋಗಿ ಸಸ್ಯ ಸಂಬಂಧಗಳು (ಪ್ಯಾಕ್) || ಗ್ರಾಫ್ಟಿಂಗ್ ಕ್ಲಿಪ್ಸ್ (ಪ್ಯಾಕ್) || ಬಡ್ಡಿಂಗ್ ನೈಫ್",
