    "LED Grow Light": "ಎಲ್ಇಡಿ ಗ್ರೋ ಲೈಟ್ || ಸ್ವಯಂ-ನೀರಿನ ಒಳಾಂಗಣ ಮಡಕೆ || ಒಳಾಂಗಣ ಸಸ್ಯ ತೇವಾಂಶದ ತಟ್ಟೆ || ಟೆರಾರಿಯಂ ಕಂಟೈನರ್ || ಗಾಳಿಯನ್ನು ಶುದ್ಧೀಕರಿಸುವ ಸಸ್ಯದ ನಿಲುವು || ಆರ್ದ್ರತೆಯ ಬೆಣಚುಕಲ್ಲು ತಟ್ಟೆ || ಇಂಡೋರ್ ಪ್ಲಾಂಟ್ ಮಿಸ್ಟಿಂಗ್ ಸ್ಪ್ರೇ ಬಾಟಲ್ || ಅಲಂಕಾರಿಕ ಒಳಾಂಗಣ ಸಸ್ಯ ಸ್ಟ್ಯಾಂಡ್ || ನಿಧಾನ-ಬಿಡುಗಡೆ ಸಸ್ಯ ಆಹಾರ ಸ್ಪೈಕ್‌ಗಳು || ಕೀಟ/ಬಟರ್ಫ್ಲೈ ಹೋಟೆಲ್ || ಸ್ಮಾರ್ಟ್ ಮಣ್ಣಿನ ತೇವಾಂಶ ಸಂವೇದಕ || ವೈ-ಫೈ ನೀರಾವರಿ ನಿಯಂತ್ರಕ || ಅಪ್ಲಿಕೇಶನ್ ಆಧಾರಿತ ಸಸ್ಯ ಆರೋಗ್ಯ ಸಂವೇದಕ || ಸ್ವಯಂಚಾಲಿತ ಹನಿ ನೀರಾವರಿ ಟೈಮರ್ || ಚಲನೆಯ ಸಂವೇದಕದೊಂದಿಗೆ ಸೌರ ಉದ್ಯಾನದ ಬೆಳಕು || ಬ್ಲೂಟೂತ್ ಮಣ್ಣು ಪರೀಕ್ಷಾ ಸಾಧನ || ಚೈನೀಸ್ ಆಲದ ಫಿಕಸ್ ಬೋನ್ಸೈ || ಆಲದ ಬೋನ್ಸಾಯ್ || ಬೌಗೆನ್ವಿಲ್ಲೆ ಬೋನ್ಸೈ || ಮರುಭೂಮಿ ಗುಲಾಬಿ ಬೋನ್ಸೈ ಅಡೆನಿಯಮ್ || ಮಿನಿ ರಸಭರಿತ ಮೂವರ || ಕೊಕೊಯಿಲ್ ಪ್ಲಾಂಟ್ ಕೇರ್ ಗಿಫ್ಟ್ ಸೆಟ್ || ಫಲೇನೊಪ್ಸಿಸ್ ಆರ್ಕಿಡ್ || ಚೈನೀಸ್ ಎವರ್ಗ್ರೀನ್ (ಅಗ್ಲೋನೆಮಾ) || ಮೂಕ ಬೆತ್ತ (ಡಿಫೆನ್‌ಬಾಚಿಯಾ) || ಹಾರ್ಟ್ಲೀಫ್ ಫಿಲೋಡೆಂಡ್ರಾನ್ || ಕ್ಯಾಲಥಿಯಾ || ಬೇಬಿ ರಬ್ಬರ್ ಪ್ಲಾಂಟ್ (ಪೆಪೆರೋಮಿಯಾ) || ಪಿಟೀಲು ಎಲೆ ಅಂಜೂರ || ರಬ್ಬರ್ ಪ್ಲಾಂಟ್ || ಜೇಡ್ ಪ್ಲಾಂಟ್ || ಕ್ರೋಟನ್ || ಅಲೋವೆರಾ || ಸಿಲಿಂಡರಾಕಾರದ ಹಾವಿನ ಗಿಡ || ಹಣದ ಮರ || ಡ್ವಾರ್ಫ್ ಅಂಬ್ರೆಲಾ ಟ್ರೀ (ಷೆಫ್ಲೆರಾ) || ಆಫ್ರಿಕನ್ ಮಾಸ್ಕ್ ಪ್ಲಾಂಟ್ (ಅಲೋಕಾಸಿಯಾ) || ಆನೆ ಕಿವಿ (ಕೊಲೊಕಾಸಿಯಾ) || ವೈಟ್ ಬರ್ಡ್ ಆಫ್ ಪ್ಯಾರಡೈಸ್ (ಸ್ಟ್ರೆಲಿಟ್ಜಿಯಾ) || ಪ್ರೇಯರ್ ಪ್ಲಾಂಟ್ (ಮರಾಂತ) || ಮಾರ್ಬಲ್ ಕ್ವೀನ್ ಪೊಥೋಸ್ || ವೈವಿಧ್ಯಮಯ ಮಾನ್ಸ್ಟೆರಾ || ಗೋಲ್ಡನ್ ಹಹಿನಿ ಹಾವಿನ ಗಿಡ || ತರಹೇವಾರಿ ಸ್ಪೈಡರ್ ಪ್ಲಾಂಟ್ || ಇಂಗ್ಲೀಷ್ ಐವಿ || ಹೃದಯಗಳ ಸರಮಾಲೆ || ಮುತ್ತಿನ ಸರ || ಬ್ಲಶಿಂಗ್ ಫಿಲೋಡೆಂಡ್ರಾನ್ (ಕೆಂಪು) || ಸ್ವಿಸ್ ಚೀಸ್ ಪ್ಲಾಂಟ್ (ಮಾನ್ಸ್ಟೆರಾ) || ಪಿಂಕ್ ಪ್ರಿನ್ಸೆಸ್ ಫಿಲೋಡೆಂಡ್ರಾನ್",
