    "Arrowhead Plant (Syngonium)": "ಬಾಣದ ಹೆಡ್ ಸಸ್ಯ (ಸಿಂಗೊನಿಯಮ್) || ಸಿಬು ಬ್ಲೂ ಪೊಥೋಸ್ || ಅಂಥೂರಿಯಂ || ಆಫ್ರಿಕನ್ ವೈಲೆಟ್ || ಫ್ಲೇಮಿಂಗ್ ಕೇಟಿ (ಕಲಾಂಚೋ) || ಮನಿ ಪ್ಲಾಂಟ್ (ವಾಟರ್ ಕಲ್ಚರ್) || ಬಾಣದ ಹೆಡ್ (ನೀರಿನ ಸಂಸ್ಕೃತಿ) || ಫಿಲೋಡೆಂಡ್ರಾನ್ (ಜಲ ಸಂಸ್ಕೃತಿ) || ಅದೃಷ್ಟದ ಬಿದಿರು || ನರ ಸಸ್ಯ (ಫಿಟ್ಟೋನಿಯಾ) || ಮಗುವಿನ ಕಣ್ಣೀರು (ಪಿಲಿಯಾ) || ಸ್ಪೈಕ್ಮಾಸ್ (ಕ್ಲಬ್ ಮಾಸ್) || ನವಿಲು ಗಿಡ (ಕ್ಯಾಲಥಿಯಾ ಮಕೊಯಾನ) || ಪಾರ್ಲರ್ ಪಾಮ್ || ಚೈನೀಸ್ ಮನಿ ಪ್ಲಾಂಟ್ (ಪೈಲಿಯಾ ಪೆಪೆರೋಮಿಯೋಡ್ಸ್) || ಫಿಲೋಡೆಂಡ್ರಾನ್ ಗ್ಲೋರಿಯೊಸಮ್",
    "Cebu Blue Pothos": "ರಾಣಿ ಅಂತೂರಿಯಂ || ವೈವಿಧ್ಯಮಯ ಮಾನ್ಸ್ಟೆರಾ ಅಡಾನ್ಸೋನಿ || ಕಪ್ಪು ಚಿನ್ನದ ಫಿಲೋಡೆನ್ಡ್ರಾನ್ (ಮೆಲನೋಕ್ರಿಸಮ್) || ಕ್ರೇಪ್ ಜಾಸ್ಮಿನ್ (ನಂದಿಯಾರ್ ವಟ್ಟೈ) || ಪೆರೆಗ್ರಿನಾ (ಜಟ್ರೋಫಾ) || ಚಿನ್ನದ ದಿಬ್ಬ ದುರಂತ || ಕಾಪರ್ಲೀಫ್ (ಅಕಲಿಫಾ) || ಪರ್ಪಲ್ ಫಾಲ್ಸ್ ಎರಂಥೆಮಮ್ || ಕ್ಯಾರಿಕೇಚರ್ ಪ್ಲಾಂಟ್ (ಗ್ರಾಪ್ಟೋಫಿಲಮ್) || ಮಾರಿಗೋಲ್ಡ್ || ಕಾಕ್ಸ್‌ಕಾಂಬ್ (ಸೆಲೋಸಿಯಾ) || ಪೆಟುನಿಯಾ || ಜಿನ್ನಿಯಾ || ಸನ್ ರೋಸ್ / ಮಾಸ್ ರೋಸ್ (ಪೋರ್ಟುಲಾಕಾ) || ವಿಂಕಾ / ಸದಾಬಹರ್ || ಈಜಿಪ್ಟಿಯನ್ ಸ್ಟಾರ್ ಕ್ಲಸ್ಟರ್ (ಪೆಂಟಾಸ್) || ಮೆಕ್ಸಿಕನ್ ಪೆಟುನಿಯಾ (ರುಯೆಲಿಯಾ) || ಕಂಬಳಿ ಹೂ (ಗೈಲಾರ್ಡಿಯಾ) || ದುರಂತ ಹೆಡ್ಗೆ || ಕಾಪರ್ಲೀಫ್ ಹೆಡ್ಜ್ || ಕಾಡು ಮಲ್ಲಿಗೆ ಮುಳ್ಳು || ಅಳುವ ಅಂಜೂರದ ಹೆಡ್ಜ್ || ವೆಡೆಲಿಯಾ || ಬಹುವಾರ್ಷಿಕ ಕಡಲೆಕಾಯಿ || ಜೋಯ್ಸಿಯಾ ಹುಲ್ಲು || ಜೋಸೆಫ್\\ || ಮೊಂಡೋ ಹುಲ್ಲು || ಸ್ಪೈಡರ್ ಪ್ಲಾಂಟ್ (ಗಡಿ ಬಳಕೆ) || ಮೆಕ್ಸಿಕನ್ ಹೀದರ್ (ಕುಫಿಯಾ) || ಬಿಳಿ ಫ್ರಾಂಗಿಪಾನಿ || ಗುಲ್ಮೊಹರ್ / ಜ್ವಾಲೆಯ ಮರ || ಗೋಲ್ಡನ್ ಶವರ್ ಟ್ರೀ || ಭಾರತೀಯ ಕಾರ್ಕ್ ಮರ || ರಾಣಿ\\",
