    "Pink Trumpet Tree (Tabebuia)": "ಪಿಂಕ್ ಟ್ರಂಪೆಟ್ ಟ್ರೀ (ಟಬೆಬುಯಾ) || ಆಫ್ರಿಕನ್ ಟುಲಿಪ್ ಮರ || ಅಶೋಕ ಮರ || ಕಾಪರ್ಪಾಡ್ / ಹಳದಿ ಪೊಯಿನ್ಸಿಯಾನಾ || ಭಾರತೀಯ ಬಾದಾಮಿ || ಆಲದ ಮರ || ಪೀಪಲ್ ಮರ || ಮಳೆ ಮರ || ಬೆಂಗಾಲ್ ಕ್ಲಾಕ್ ವೈನ್ (ಥನ್‌ಬರ್ಗಿಯಾ) || ಕಿತ್ತಳೆ ಕಹಳೆ ಬಳ್ಳಿ || ಕಾರ್ಡಿನಲ್ ಕ್ರೀಪರ್ (ಇಪೊಮಿಯಾ) || ಚಿನ್ನದ ಬಿದಿರು || ಹೆಡ್ಜ್ ಬಿದಿರು || ಗಂಡು ಬಿದಿರು / ಕಲ್ಕತ್ತಾ ಬಿದಿರು || ಡುರಾಂತ ಟೋಪಿಯಾರಿ || ಫಿಕಸ್ ಟೋಪಿಯರಿ || ಕಾಮಿನಿ ಟೋಪಿಯಾರಿ || ಗೋಲ್ಡನ್ ಕೇನ್ ಪಾಮ್ || ತೆಂಗಿನಕಾಯಿ || ರಾಯಲ್ ಪಾಮ್ || ಪಿಗ್ಮಿ ಖರ್ಜೂರ || ಮೀನಿನ ಬಾಲ || ಚೈನೀಸ್ ಫ್ಯಾನ್ ಪಾಮ್ || ಮೆಕ್ಸಿಕನ್ ಫ್ಯಾನ್ ಪಾಮ್ (ವಾಷಿಂಗ್ಟೋನಿಯಾ) || ಚೈನೀಸ್ ವಿಂಡ್ಮಿಲ್ ಪಾಮ್ || ಬಾಟಲ್ ಪಾಮ್ || ತ್ರಿಕೋನ ಪಾಮ್ || ಬಿಸ್ಮಾರ್ಕ್ ಪಾಮ್ || ಸಾಗೋ ಪಾಮ್ (ವ್ಯಾಪಾರ) || ಮಕರ್ತೂರ್ ಪಾಮ್ || ಲೇಡಿ ಪಾಮ್ || ತಾಳೆ ಪಾಮ್ || ಸಾಗೋ ಪಾಮ್ (ಸೈಕಾಡ್) || ರಾಣಿ ಸಾಗೋ || ರಂಪ್\\ || ರಟ್ಟಿನ ಪಾಮ್ || ಚೆಸ್ಟ್ನಟ್ ಡಿಯೋನ್ || Zululand Cycad (Encephalartos) || ಝಮಿಯಾ ಪಾಮ್ (ಮ್ಯಾಕ್ರೋಜಾಮಿಯಾ) || ಮೆಕ್ಸಿಕನ್ ಸ್ನೋಬಾಲ್ (ಎಚೆವೆರಿಯಾ) || ಜೀಬ್ರಾ ಪ್ಲಾಂಟ್ (ಹಾವೋರ್ಥಿಯಾ) || ಬುರೋ\\ || ಗುಂಡಿಗಳ ದಾರ || ಲೇಸ್ ಅಲೋ || ಟಾರ್ಚ್ ಅಲೋ || ಪಾಂಡ ಸಸ್ಯ || ಸಾವಿರ ಮಾತೆ || ವೇಲ್ ಫಿನ್ ಸ್ನೇಕ್ ಪ್ಲಾಂಟ್ || ಆನೆ ಪೊದೆ || ಘೋಸ್ಟ್ ಪ್ಲಾಂಟ್",
