    "Century Plant (Agave)": "ಶತಮಾನದ ಸಸ್ಯ (ಅಗೇವ್) || ಫಾಕ್ಸ್ಟೇಲ್ ಭೂತಾಳೆ || ಪೆನ್ಸಿಲ್ ಕಳ್ಳಿ || ಆಫ್ರಿಕನ್ ಹಾಲಿನ ಮರ || ಜೀವಂತ ಕಲ್ಲುಗಳು (ಲಿಥಾಪ್ಸ್) || ಬಾಳೆಹಣ್ಣಿನ ಸರ || ಆಕ್ಸ್ ಟಂಗ್ ಪ್ಲಾಂಟ್ (ಗ್ಯಾಸ್ಟೇರಿಯಾ) || ಮರುಭೂಮಿ ಗುಲಾಬಿ || ಮೂನ್ ಸ್ಟೋನ್ಸ್ (Pachyphytum) || ಪೆರುವಿಯನ್ ಆಪಲ್ ಕ್ಯಾಕ್ಟಸ್ || ಗೋಲ್ಡನ್ ಬ್ಯಾರೆಲ್ ಕ್ಯಾಕ್ಟಸ್ || ಬನ್ನಿ ಇಯರ್ ಕ್ಯಾಕ್ಟಸ್ (ಒಪುಂಟಿಯಾ) || ಚಂದ್ರ ಕಳ್ಳಿ || ಬಿಷಪ್\\ || ಓಲ್ಡ್ ಮ್ಯಾನ್ ಕಳ್ಳಿ || ಕ್ರಿಸ್ಮಸ್ ಕ್ಯಾಕ್ಟಸ್ || ಇಲಿ ಬಾಲ ಕಳ್ಳಿ || ಲೇಡಿ ಫಿಂಗರ್ ಕ್ಯಾಕ್ಟಸ್ (ಮ್ಯಾಮಿಲೇರಿಯಾ) || ಮುಳ್ಳು ಪೇರಳೆ || ಎಚೆವೆರಿಯಾ ಟೇಬಲ್ ಟಾಪ್ || ಬೇಬಿ ರಬ್ಬರ್ ಪ್ಲಾಂಟ್ (ಟೇಬಲ್ ಟಾಪ್) || ನರ ಸಸ್ಯ (ಟೇಬಲ್ ಟಾಪ್) || ಗ್ಲೋಕ್ಸಿನಿಯಾ || ಚೈನೀಸ್ ಮನಿ ಪ್ಲಾಂಟ್ (ಟೇಬಲ್ ಟಾಪ್) || ಮಿನಿ ಎಚೆವೆರಿಯಾ || ತಿಂಬಲ್ ಕಳ್ಳಿ || ಬೇಬಿ\\ || ಟೇಬಲ್ ಫರ್ನ್ (ಮಿನಿ) || ಚೈನೀಸ್ ಬಾನಿಯನ್ ಬೋನ್ಸೈ (ಫಿಕಸ್) || ಜೇಡ್ ಬೋನ್ಸೈ || ಪ್ರೇಮ್ನಾ ಬೋನ್ಸಾಯ್ || ಚೈನೀಸ್ ಜುನಿಪರ್ ಬೋನ್ಸೈ || ಡೆಂಡ್ರೋಬಿಯಂ ಆರ್ಕಿಡ್ || ನೀಲಿ ವಂದಾ || ಮಾತ್ ಆರ್ಕಿಡ್ (ಫಲೇನೊಪ್ಸಿಸ್) || ಕೊರ್ಸೇಜ್ ಆರ್ಕಿಡ್ (ಕ್ಯಾಟ್ಲಿಯಾ) || ಡ್ಯಾನ್ಸಿಂಗ್ ಲೇಡಿ ಆರ್ಕಿಡ್ (ಆನ್ಸಿಡಿಯಮ್) || ಸಿಂಬಿಡಿಯಮ್ ಆರ್ಕಿಡ್ || ಫಿಲಿಪೈನ್ ಗ್ರೌಂಡ್ ಆರ್ಕಿಡ್ || ಮೊಕರ ಆರ್ಕಿಡ್ || ಸ್ಕಾರ್ಲೆಟ್ ಸ್ಟಾರ್ (ಗುಜ್ಮೇನಿಯಾ) || ಜ್ವಾಲೆಯ ಕತ್ತಿ (ವ್ರೀಸಿಯಾ) || ಸಿಲ್ವರ್ ವಾಸ್ ಪ್ಲಾಂಟ್ (Aechmea) || ಬ್ಲಶಿಂಗ್ ಬ್ರೊಮೆಲಿಯಾಡ್ (ನಿಯೋರೆಜೆಲಿಯಾ) || ಸ್ಪ್ಯಾನಿಷ್ ಮಾಸ್ (ಏರ್ ಪ್ಲಾಂಟ್) || ಬೋಸ್ಟನ್ ಜರೀಗಿಡ || ಹಕ್ಕಿ\\ || ಮೈಡೆನ್ಹೇರ್ ಜರೀಗಿಡ || ಸ್ಟಾಘೋರ್ನ್ ಜರೀಗಿಡ || ಮೊಲ\\",
