    "Silver Lace Fern (Table Fern)": "ಸಿಲ್ವರ್ ಲೇಸ್ ಜರೀಗಿಡ (ಟೇಬಲ್ ಫರ್ನ್) || ಉಷ್ಣವಲಯದ ಪಿಚರ್ ಪ್ಲಾಂಟ್ (ನೆಪೆಂಥೀಸ್) || ವೀನಸ್ ಫ್ಲೈಟ್ರಾಪ್ || ಕೇಪ್ ಸಂಡ್ಯೂ || ಪರ್ಪಲ್ ಪಿಚರ್ ಪ್ಲಾಂಟ್ (ಸರ್ರಾಸೇನಿಯಾ) || ನೀರು ಹಯಸಿಂತ್ || ನೀರು ಲೆಟಿಸ್ || ಕ್ಯಾಟೈಲ್ (ಬುಲ್ರಶ್) || ಪಪೈರಸ್ || ನೀರು ನೈದಿಲೆ || ಕಮಲ || ಈಲ್ ಗ್ರಾಸ್ (ವಲ್ಲಿಸ್ನೇರಿಯಾ) || ಆನೆ ಕಿವಿ (ಕೊಳ) || ಹಾರ್ಟ್ಲೀಫ್ ಫಿಲೋಡೆಂಡ್ರಾನ್ (ಲಂಬ) || ಬಾಣದ ತುದಿ (ಲಂಬ) || ಬೋಸ್ಟನ್ ಜರೀಗಿಡ (ಲಂಬ) || ಮಾಸ್ ರೋಸ್ (ಲಂಬ) || ಸ್ಪೈಡರ್ ಪ್ಲಾಂಟ್ (ಹಸಿರು ಗೋಡೆ) || ಅಲೆದಾಡುವ ಯಹೂದಿ (ಟ್ರೇಡ್ಸ್ಕಾಂಟಿಯಾ) || ಬೇಬಿ ರಬ್ಬರ್ ಪ್ಲಾಂಟ್ (ಹಸಿರು ಗೋಡೆ) || ಇಕ್ಸೋರಾ (ಟೆರೇಸ್) || ಕುಬ್ಜ ಪೇರಲ || ಮಡಗಾಸ್ಕರ್ ಡ್ರ್ಯಾಗನ್ ಟ್ರೀ (ಡ್ರಾಕೇನಾ ಮಾರ್ಜಿನಾಟಾ) || ಮಿನಿಯೇಚರ್ ರೋಸ್ || ಪಚ್ಚೆ ಏರಿಳಿತ ಪೆಪೆರೋಮಿಯಾ || ಎಚೆವೆರಿಯಾ (ಬಾಲ್ಕನಿ) || ಟ್ರೇಲಿಂಗ್ ವರ್ಬೆನಾ || ಸ್ವೀಡಿಷ್ ಐವಿ (ಪ್ಲೆಕ್ಟ್ರಾಂಥಸ್) || ಮಿಸ್ಟ್ಲೆಟೊ ಕ್ಯಾಕ್ಟಸ್ (ರಿಪ್ಸಾಲಿಸ್) || ನಿಂಬೆ || ಸುಣ್ಣ || ಮಾವು || ಪೇರಲ || ದಾಳಿಂಬೆ || ಸೀತಾಫಲ || ಪಪ್ಪಾಯ || ಮಲ್ಬೆರಿ || ಜಮೈಕಾದ ಚೆರ್ರಿ / ಸ್ಟ್ರಾಬೆರಿ ಮರ || ಭಾರತೀಯ ಜುಜುಬಿ || ಕುಳ್ಳ ತೆಂಗಿನಕಾಯಿ || ನಕ್ಷತ್ರ ಫಲ || ಪ್ಯಾಶನ್ ಫ್ರೂಟ್ || ಮೇಣದ ಸೇಬು || ಸ್ಟ್ರಾಬೆರಿ || ಅಂಜೂರ || ಡ್ರ್ಯಾಗನ್ ಫ್ರೂಟ್ || ದ್ರಾಕ್ಷಿಗಳು || ಸಪೋಟ / ಚಿಕೂ || ಹಲಸು || ತುಳಸಿ",
