    "Mint": "ಪುದೀನಾ || ಕೊತ್ತಂಬರಿ ಸೊಪ್ಪು || ಓರೆಗಾನೊ || ರೋಸ್ಮರಿ || ಥೈಮ್ || ಪವಿತ್ರ ತುಳಸಿ (ತುಳಸಿ) || ಕಹಿಗಳ ರಾಜ (ನಿಲವೆಂಬು) || ಗೋಟು ಕೋಲ (ವಲ್ಲರೈ) || ಅಲೋವೆರಾ (ಔಷಧೀಯ) || ಭಾರತೀಯ ನೆಲ್ಲಿಕಾಯಿ (ಆಮ್ಲಾ) || ಅಶ್ವಗಂಧಾ || ಬೇವು || ಮಲಬಾರ್ ಕಾಯಿ (ಅಡತೊಡೈ) || ಲೆಮೊನ್ಗ್ರಾಸ್ || ಗುಲಾಬಿ ಪರಿಮಳದ ಜೆರೇನಿಯಂ || ಲ್ಯಾವೆಂಡರ್ || ವೆಟಿವರ್ || ಕರಿಮೆಣಸು || ಶುಂಠಿ || ಅರಿಶಿನ || ಕರಿಬೇವಿನ ಎಲೆ || ದಾಲ್ಚಿನ್ನಿ || ಲವಂಗ || ತುಳಸಿ || ಬೇಲ್ / ಬಿಲ್ವ || ಪೀಪಲ್ (ಪವಿತ್ರ) || ಕಮಲ (ಪವಿತ್ರ) || ಅರೇಬಿಯನ್ ಮಲ್ಲಿಗೆ || ಚಂಪಕ || ಇಕ್ಸೋರಾ (ಚಿಟ್ಟೆ) || ಲಂಟಾನ (ಚಿಟ್ಟೆ) || ಇಂಡಿಯನ್ ಬರ್ತ್‌ವರ್ಟ್ (ಅರಿಸ್ಟೋಲೋಚಿಯಾ)",
