    "Beach Cabbage (Scaevola)": "ಬೀಚ್ ಎಲೆಕೋಸು (ಸ್ಕೇವೊಲಾ) || ಪೋರ್ಟಿಯಾ ಮರ || ಕಾಡು ಮಲ್ಲಿಗೆ (ಕರಾವಳಿ) || ಮಡಗಾಸ್ಕರ್ ಬಾದಾಮಿ || ಅರ್ಜುನ || ಬಹೇದಾ || ಹರಿತಕಿ || ಕರಂಜ್ / ಪೊಂಗಮಿಯಾ || ಮಹೋಗಾನಿ || ಆಫ್ರಿಕನ್ ಮಹೋಗಾನಿ || ಬಿಳಿ ದೇವದಾರು || ಭಾರತೀಯ ಮಹೋಗಾನಿ (ಟೂನ್) || ಕರ್ಪೂರ ಮರ || ಜಾಮೂನ್ || ಹುಣಸೆಹಣ್ಣು || ಮಹುವಾ || ಬಕುಲ್ || ರುದ್ರಾಕ್ಷ || ಪಲಾಶ್ / ಕಾಡಿನ ಜ್ವಾಲೆ || ರೇಷ್ಮೆ ಹತ್ತಿ ಮರ || ಸಮುದ್ರ ದಾಸವಾಳ || ಅಲೆಕ್ಸಾಂಡ್ರಿಯನ್ ಲಾರೆಲ್ || ನಿಜ ಅಶೋಕಾ || ಜಕರಂದ || ಕದಂಬ || ಪುತ್ರಂಜಿವಾ || ಪಿಂಕ್ ಶವರ್ ಟ್ರೀ || ಆರ್ಕಿಡ್ ಮರ (ನೇರಳೆ) || ಆರ್ಕಿಡ್ ಮರ (ಬಿಳಿ) || ಹಳದಿ ತಬೆಬುಯಾ || ಬೆಳ್ಳಿ ಕಹಳೆ ಮರ || ಬಿಳಿ ಕಹಳೆ ಮರ || ಫಿರಂಗಿ ಮರ || ಸಾಸೇಜ್ ಮರ || ಅಳುವ ಅಂಜೂರದ ಮರ || ಭಾರತೀಯ ಲಾರೆಲ್ ಫಿಗ್ || ಫಿಕಸ್ ಪಾಂಡಾ || ಮ್ಯಾಗ್ನೋಲಿಯಾ || ಆಸ್ಟ್ರೇಲಿಯನ್ ಪೈನ್ || ನಾರ್ಫೋಕ್ ಐಲ್ಯಾಂಡ್ ಪೈನ್ || ಕುಕ್ ಪೈನ್ || ಬಾಬಾಬ್ || ಮಂಕಿ ಪಜಲ್ ಟ್ರೀ || ಡ್ರ್ಯಾಗನ್ ರಕ್ತದ ಮರ || ಅಗ್ಲೋನೆಮಾ ಕೆಂಪು || ಅಗ್ಲೋನೆಮಾ ಬೆಳ್ಳಿ ಬೇ || ಫಿಲೋಡೆಂಡ್ರಾನ್ ಕ್ಸನಾಡು || ಫಿಲೋಡೆಂಡ್ರಾನ್ ಸೆಲ್ಲೋಮ್ || ಮಾನ್ಸ್ಟೆರಾ ಡೆಲಿಸಿಯೋಸಾ || ಡಿಫೆನ್‌ಬಾಚಿಯಾ ಕ್ಯಾಮಿಲ್ಲೆ",
