    "Dracaena Marginata": "ಡ್ರಾಕೇನಾ ಮಾರ್ಜಿನಾಟಾ || ಡ್ರಾಕೇನಾ ಕಾಂಪ್ಯಾಕ್ಟಾ || ಡ್ರಾಕೇನಾ ಸಾಂಗ್ ಆಫ್ ಇಂಡಿಯಾ || ಜಮೈಕಾದ ಡ್ರಾಕೇನಾ ಹಾಡು || ಕಾರ್ಡಿಲೈನ್ ಕೆಂಪು || ಕಾರ್ಡಿಲೈನ್ ಗ್ರೀನ್ (ಟಿ ಪ್ಲಾಂಟ್) || ಅಕಲಿಫಾ ಹಸಿರು || ಮಿಂಗ್ ಅರಾಲಿಯಾ || ಬಗೆಬಗೆಯ ಅರಲಿಯಾ || ಹಸಿರು ಅರಾಲಿಯಾ || ವೈವಿಧ್ಯಮಯ ಶೆಫ್ಲೆರಾ || ಹಸಿರು ಶೆಫ್ಲೆರಾ || ಡುರಾಂಟಾ ಗೋಲ್ಡನ್ ಎಡ್ಜ್ || ಬಗೆಬಗೆಯ ದುರಂತ || ಕಾಮಿನಿ (ಕಿತ್ತಳೆ ಮಲ್ಲಿಗೆ) || ಗಾರ್ಡೇನಿಯಾ || ಹಳದಿ ಬೆಲ್ಸ್ (ಟೆಕೋಮಾ) || ಕಿತ್ತಳೆ ಟೆಕೋಮಾ || ಹಳದಿ ಅಲ್ಲಮಂದಾ || ನೇರಳೆ ಅಲ್ಲಮಂದಾ || ಪಿಂಕ್ ಮುಸ್ಸೇಂಡಾ || ಬಿಳಿ ಮುಸ್ಸೆಂದಾ || ಫೈರ್‌ಬುಷ್ (ಹಮೆಲಿಯಾ ಪ್ಯಾಟೆನ್ಸ್) || ಪಟಾಕಿ ಸ್ಥಾವರ (ರಸ್ಸೆಲಿಯಾ) || ನೀಲಿ ಪ್ಲಂಬಾಗೋ || ವೈಟ್ ಪ್ಲಂಬಾಗೋ || ಕಾಡು ಮಲ್ಲಿಗೆ (ಕ್ಲೆರೊಡೆಂಡ್ರಮ್ ಇನರ್ಮೆ) || ಜ್ವಾಲೆಯ ಗ್ಲೋರಿಬೋವರ್ || ಮೆಕ್ಸಿಕನ್ ಪೆಟುನಿಯಾ (ಎತ್ತರ) || ಕುಳ್ಳ ಕ್ರಾಸಂದ್ರ || ಫಿಲಿಪೈನ್ ವೈಲೆಟ್ (ಬಾರ್ಲೇರಿಯಾ) || ಕೆಂಪು ಪೆಂಟಾಸ್ || ಪಿಂಕ್ ಪೆಂಟಾಸ್ || ಬಿಳಿ ಪೆಂಟಾಸ್ || ಹಳದಿ ಇಕ್ಸೋರಾ || ಡ್ವಾರ್ಫ್ ಇಕ್ಸೋರಾ || ಕೆಂಪು ದಾಸವಾಳ || ಹಳದಿ ದಾಸವಾಳ || ಬಗೆಬಗೆಯ ದಾಸವಾಳ || ಸ್ವರ್ಗದ ಹಕ್ಕಿ || ಲೋರೊಪೆಟಲಮ್ (ಚೀನೀ ಫ್ರಿಂಜ್ ಫ್ಲವರ್) || ಭಾರತೀಯ ಹಾಥಾರ್ನ್ || ಬೋಟ್ ಲಿಲಿ (ರಿಯೋ ತ್ರಿವರ್ಣ) || ಅಲೆದಾಡುವ ಯಹೂದಿ (ಜೆಬ್ರಿನಾ) || ರೆಡ್ ಆಲ್ಟರ್ನಂಥೆರಾ || ಹಳದಿ ಆಲ್ಟರ್ನಂಥೆರಾ || ಹಸಿರು ಪರ್ಯಾಯ || ರಕ್ತದ ಎಲೆ (ಐರೆಸಿನ್) || ಶತಾವರಿ ಜರೀಗಿಡ || ಫಾಕ್ಸ್‌ಟೇಲ್ ಜರೀಗಿಡ",
