    "Liriope (Lily Turf)": "ಲಿರಿಯೋಪ್ (ಲಿಲಿ ಟರ್ಫ್) || ಡಯಾನೆಲ್ಲಾ (ಫ್ಲಾಕ್ಸ್ ಲಿಲಿ) || ಅಗಾಪಾಂತಸ್ (ಆಫ್ರಿಕನ್ ಲಿಲಿ) || ಡಯೆಟ್ಸ್ ಬೈಕಲರ್ (ವೈಲ್ಡ್ ಐರಿಸ್) || ಡಯಟ್ಸ್ ಗ್ರಾಂಡಿಫ್ಲೋರಾ || ಸಮಾಜ ಬೆಳ್ಳುಳ್ಳಿ || ಅಂಬ್ರೆಲಾ ಪಾಮ್ (ಡ್ವಾರ್ಫ್ ಸೈಪರಸ್) || ವೈವಿಧ್ಯಮಯ ಸ್ಕ್ರೂಪೈನ್ (ಪಾಂಡನಸ್) || ಸ್ಪೈಡರ್ ಲಿಲಿ || ಕ್ರಿನಮ್ ಲಿಲಿ || ಕ್ಯಾನ್ನಾ ಲಿಲಿ || ದಿನ ಲಿಲಿ || ರೈನ್ ಲಿಲಿ || ಬಿಳಿ ಶುಂಠಿ ನೈದಿಲೆ || ಕೆಂಪು ಶುಂಠಿ (ಆಸ್ಟ್ರಿಚ್ ಪ್ಲಮ್) || ಹೆಲಿಕೋನಿಯಾ / ಲೋಬ್ಸ್ಟರ್ ಕ್ಲಾ || ಹಲಸು || ಥುಜಾ / ಮೋರ್ಪಂಖಿ || ಪೊಡೊಕಾರ್ಪಸ್ || ನೀಲಿ ನಕ್ಷತ್ರ ಜುನಿಪರ್ || ನಂದಿನಾ (ಹೆವೆನ್ಲಿ ಬಿದಿರು) || ಯುಜೀನಿಯಾ ಹೆಡ್ಜ್ || ಬಾಕ್ಸ್ ವುಡ್ || ಫಿಲೋಡೆಂಡ್ರಾನ್ ಬಿರ್ಕಿನ್ || ಕ್ಯಾಲಡಿಯಮ್ || ಬ್ಲಾಕ್ ಮ್ಯಾಜಿಕ್ ಆನೆ ಕಿವಿ || ಅಲೋಕಾಸಿಯಾ ಪೊಲ್ಲಿ || ಪಿಂಕ್ ಸಿಂಗೋನಿಯಮ್ || ಪೀಸ್ ಲಿಲಿ ಡೊಮಿನೊ (ವಿವಿಧ) || ಕೆಂಪು ಅಂತೂರಿಯಂ || ಬಿಳಿ ಅಂತೂರಿಯಂ || ಕಿಂಬರ್ಲಿ ರಾಣಿ ಜರೀಗಿಡ || ಬ್ಲೂ ಡೇಜ್ (Evolvulus) || ಗಜಾನಿಯಾ || ಡಯಾಂಥಸ್ / ಪಿಂಕ್ಸ್ || ಸಾಲ್ವಿಯಾ || ವರ್ಬೆನಾ || ಉಣ್ಣಿಬೀಜ (ಕೊರಿಯೊಪ್ಸಿಸ್) || ಪ್ಲಮ್ ಸೆಲೋಸಿಯಾ || ಡ್ವಾರ್ಫ್ ಕೋಲಿಯಸ್ || ಅಸಹನೆಗಳು / ಬಾಲ್ಸಾಮ್ || ಬೆಗೋನಿಯಾ || ವ್ಯಾಕ್ಸ್ ಬೆಗೋನಿಯಾ || ರೆಕ್ಸ್ ಬೆಗೋನಿಯಾ || ಧೂಳಿನ ಮಿಲ್ಲರ್ || ಲ್ಯಾವೆಂಡರ್ ಹತ್ತಿ || ವರ್ಮ್ವುಡ್ (ಆರ್ಟೆಮಿಸಿಯಾ) || ಸ್ಟೋನ್ಕ್ರಾಪ್ (ಸೆಡಮ್) || ಬಗೆಬಗೆಯ ಆನೆ ಪೊದೆ || ನೀಲಿ ಚಾಕ್ ಸ್ಟಿಕ್ಸ್ (ಸೆನೆಸಿಯೊ)",
